	//
	// Get Field with container to obtain a correct layout
	//
	this.getFieldForComponentWithLabel = function($component, label, postComponent, isInline, $info) {
		var $fieldset = $('<div>');
		
		var $controlGroup = $('<div>', {class : 'form-group'});
		var requiredText = '';
		if($component.attr('required')) {
			requiredText = " (*)"
		}
		
		var labelText = "";
		if(label) {
            labelText = label + requiredText;
        }
        var $controlLabel = this.createLabel(labelText, $info);
		
		var controlColumnClass = ""
		if(!isInline) {
			controlColumnClass = this.controlColumnClass;
		}
		var $controls = $('<div>', { class : 'controls' });
		
		if(label) {
			$controlGroup.append($controlLabel);
		}
		
		if(isInline) {
			$controlGroup.append($component);
		} else {
			$controls.append($component);
			$controlGroup.append($controls);
		}
		
		if(postComponent) {
			$controlGroup.append(postComponent);
		}
		$fieldset.append($controlGroup);
		
		if(isInline) {
			return $controlGroup;
		} else {
			return $fieldset;
		}
	}

    this.createLabel = function(label, $info) {
        var $controlLabel = $('<label>', {class : 'control-label' });
        
        if(label) {
            if ($info) {
                var $line = $("<div>");
                $line.append(label);
                $infoIcon = $("<span>", { 'class' : 'glyphicon glyphicon-info-sign', 'style' : 'padding:2px' });
                $infoIcon.tooltipster({
                    content: $info,
                    theme: 'tooltipster-shadow',
                    interactive: true
                });
                $line.append($infoIcon);
                $line.append(":");
                $controlLabel.append($line);
            } else
            {
                $controlLabel.text(label + ":");
            }
        }
        return $controlLabel;
    }

    this.createPropertyField = function(propertyType, propertyValue, $info) {
		var numberFormat = new Intl.NumberFormat('en-US', { notation : "standard",
			minimumSignificantDigits :  "1",
			maximumSignificantDigits : "21",
			minimumFractionDigits : "0",
			maximumFractionDigits : "20" });

	    var isLink = propertyType.dataType === "HYPERLINK";
	    var hyperlinkLabel = null;
		if (propertyType.dataType === "CONTROLLEDVOCABULARY") {
		    if(propertyValue && propertyValue.includes(',')) {
		        //multivalue vocabulary property case
		        var values = propertyValue.split(',');
		        var result = [];
		        for(let value of values) {
		            var singleValue = this.getVocabularyLabelForTermCode(propertyType, value.trim());
                    if(propertyType.vocabulary.urlTemplate) {
                        hyperlinkLabel = singleValue;
                        singleValue = propertyType.vocabulary.urlTemplate.replace('${term}', singleValue);
                        isLink = true;
                    }
                    result.push(singleValue);
		        }
		        propertyValue = result.join(', ');
		    } else {
                propertyValue = this.getVocabularyLabelForTermCode(propertyType, propertyValue);
                if(propertyType.vocabulary.urlTemplate) {
                    hyperlinkLabel = propertyValue;
                    propertyValue = propertyType.vocabulary.urlTemplate.replace('${term}', propertyValue);
                    isLink = true;
                }
			}
		} else if (propertyType.dataType === "INTEGER" || propertyType.dataType === "REAL") {
		    if (Array.isArray(propertyValue)) {
		        propertyValue = propertyValue.map(function(v) { return v == null ? 'null' : numberFormat.format(v); }).join(', ');
		    } else {
		        propertyValue = numberFormat.format(propertyValue);
		    }
		} else if (propertyType.dataType === "ARRAY_INTEGER" || propertyType.dataType === "ARRAY_REAL") {
			var formatNumArray = function(arr) {
				return "[" + arr.map(function(v) { return v == null ? "null" : numberFormat.format(v); }).join(", ") + "]";
			};
			if (Array.isArray(propertyValue) && Array.isArray(propertyValue[0])) {
				propertyValue = propertyValue.map(function(arr) { return arr == null ? "null" : formatNumArray(arr); }).join(', ');
			} else {
				propertyValue = formatNumArray(propertyValue);
			}
		} else if (propertyType.dataType === "ARRAY_STRING" || propertyType.dataType === "ARRAY_TIMESTAMP") {
			var formatStrArray = function(arr) {
				return "[" + arr.map(function(v) { return v == null ? "null" : '"' + v + '"'; }).join(", ") + "]";
			};
			if (Array.isArray(propertyValue) && Array.isArray(propertyValue[0])) {
				propertyValue = propertyValue.map(function(arr) { return arr == null ? "null" : formatStrArray(arr); }).join(', ');
			} else {
				propertyValue = formatStrArray(propertyValue);
			}
		}
        return this._createField(isLink, propertyType.label, propertyValue, propertyType.code, null, null, hyperlinkLabel, $info);
	}
	
	this.getFieldForLabelWithText = function(label, text, id, postComponent, cssForText) {
		return this._createField(false, label, text, id, postComponent, cssForText);
	}
	
    this._createField = function(hyperlink, label, text, id, postComponent, cssForText, hyperlinkLabel, $info) {
		var $fieldset = $('<div>');
		
		var $controlGroup = $('<div>', {class : 'form-group'});
		
        var $controlLabel = this.createLabel(label, $info);
		
		var $controls = $('<div>', {class : 'controls' });
		
		$controlGroup.append($controlLabel);
		$controlGroup.append($controls);
		if(postComponent) {
			$controlGroup.append(postComponent);
		}
		$fieldset.append($controlGroup);
		
		var $component = $("<p>", {'class' : 'form-control-static', 'style' : 'border:none; box-shadow:none; background:transparent; word-wrap: break-word;'}); //white-space: pre-wrap;
		if(cssForText) {
			$component.css(cssForText);
		}
		
		if(text) {
		    if(typeof(text) != 'string') { // Array case
                text = text.join(", ");
            }
			text = text.replace(/(?:\r\n|\r|\n)/g, '\n'); //Normalise carriage returns
		}

		if(hyperlink) {
		    $component.html(this.asHyperlink(text, hyperlinkLabel));
		} else {
		    if(text && text.includes('\n')) {
		        var lines = text.split('\n');
		        for(var lineIndex = 0; lineIndex < lines.length; lineIndex++) {
		            if(lineIndex != 0) {
		                $component.append($("<br>"));
		            }
		            var textNode = document.createTextNode(lines[lineIndex].replace(/ /g, '\u00a0'));
                    $component.append(textNode);
		        }
		    } else {
		        $component.text(text);
		    }
		}
		
		if(id) {
			$component.attr('id', this.prepareId(id));
		}
		$controls.append($component);
		
		return $fieldset;
	}
	
	this.asHyperlink = function(text, label) {
		return $("<a>", { "href" : text, "target" : "_blank"}).append((label ? label : text));
	}

	//
	// Get Field from property
	//
	this.getVocabularyLabelForTermCode = function(propertyType, data) {
		var vocabulary = propertyType.vocabulary;
		if(vocabulary) {
		    if(Array.isArray(data)) {
		        var codes = [];
		        for(termCode of data) {
                    for(var tIdx = 0; tIdx < vocabulary.terms.length; tIdx++) {
                        if(vocabulary.terms[tIdx].code === termCode &&
                            vocabulary.terms[tIdx].label) {
                            codes.push(vocabulary.terms[tIdx].label);
                        }
                    }
		        }
		        return codes.sort().toString();
		    } else {
		        var termCode = data;
                for(var tIdx = 0; tIdx < vocabulary.terms.length; tIdx++) {
                    if(vocabulary.terms[tIdx].code === termCode &&
                        vocabulary.terms[tIdx].label) {
                        return vocabulary.terms[tIdx].label;
                    }
                }
			}
		}
		return termCode;
	}

	this.getFieldForPropertyType = function(propertyType, timestampValue) {
	    return this.getFieldForPropertyType(propertyType, timestampValue, false, "-" + mainController.getNextId());
	}
	
	this.getFieldForPropertyType = function(propertyType, timestampValue, isMultiValue, idSuffix) {
		var $component = null;
		if(!idSuffix) {
		    idSuffix = mainController.getNextId();
		}

		if (propertyType.dataType === "BOOLEAN") {
			$component = this._getBoolean2Field(propertyType.code + idSuffix, propertyType.description, propertyType.mandatory);
		} else if (propertyType.dataType === "CONTROLLEDVOCABULARY") {
			var vocabulary = profile.getVocabularyByCode(propertyType.vocabulary.code);
			$component = this._getDropDownFieldForVocabulary(propertyType.code + idSuffix, vocabulary.terms, propertyType.description, propertyType.mandatory, isMultiValue);
		} else if (propertyType.dataType === "HYPERLINK") {
			$component = this._getInputField("url", propertyType.code + idSuffix, propertyType.description, null, propertyType.mandatory);
		} else if (propertyType.dataType === "INTEGER") {
			$component = this._getNumberInputField(propertyType.code + idSuffix, propertyType.description, '1', propertyType.mandatory);
		} else if (["MULTILINE_VARCHAR", "JSON"].includes(propertyType.dataType)) {
			$component = this._getTextBox(propertyType.code + idSuffix, propertyType.description, propertyType.mandatory);
			if(profile.isForcedMonospaceFont(propertyType)) {
				$component.css("font-family", "Consolas, Monaco, Lucida Console, Liberation Mono, DejaVu Sans Mono, Bitstream Vera Sans Mono, Courier New, monospace");
			}
		} else if (propertyType.dataType === "REAL") {
			$component = this._getNumberInputField(propertyType.code + idSuffix, propertyType.description, 'any', propertyType.mandatory);
		} else if (propertyType.dataType === "TIMESTAMP") {
			$component = this._getDatePickerField(propertyType.code + idSuffix, propertyType.description, propertyType.mandatory, false, timestampValue);
		} else if (propertyType.dataType === "DATE") {
			$component = this._getDatePickerField(propertyType.code + idSuffix, propertyType.description, propertyType.mandatory, true, timestampValue);
		} else if (propertyType.dataType === "VARCHAR") {
            $component = this._getInputField("text", propertyType.code + idSuffix, propertyType.description, null, propertyType.mandatory);
        } else if (["ARRAY_STRING", "ARRAY_INTEGER", "ARRAY_REAL", "ARRAY_TIMESTAMP"].includes(propertyType.dataType)) {
			const placeholderByDataType  = {
				ARRAY_TIMESTAMP: '["yyyy-MM-dd HH:mm:ss ZZ", ...]',
				ARRAY_STRING: '["Str1", "Str2", ...]',
				ARRAY_INTEGER: '[1, 2, ...]',
				ARRAY_REAL: '[0.1, 0.2, ...]'
			}
            $component = this._getInputField("text", propertyType.code + idSuffix,
				placeholderByDataType[propertyType.dataType], null, propertyType.mandatory);
        } else if (propertyType.dataType === "XML") {
			$component = this._getTextBox(propertyType.code + idSuffix, propertyType.description, propertyType.mandatory);
		} else if (propertyType.dataType === "SAMPLE") {
		    var sampleTypeCode = propertyType.sampleTypeCode;
		    var sampleTypePlaceholder = null;
		    if(!sampleTypeCode) {
		        sampleTypePlaceholder = " of any type"
		    } else {
		        sampleTypePlaceholder = " of type " + Util.getDisplayNameFromCode(sampleTypeCode);
		    }
		    $component = new SampleField(propertyType.mandatory, "Select " + ELNDictionary.Sample + sampleTypePlaceholder, sampleTypeCode, undefined, undefined, isMultiValue);
		}
		
		return $component;
	}
	
	//
	// Read/Write Fields
	//
	this.setFieldValue = function(propertyType, $field, value) {
		if(propertyType.dataType === "BOOLEAN") {
		    if(value === 'true') {
		        value = 'true';
		    } else if (value === 'false') {
		        value = 'false';
		    } else {
		        value = '';
		    }
			$field.val(value);
		} else if(propertyType.dataType === "TIMESTAMP" || propertyType.dataType === "DATE") {
			var displayValue = propertyType.dataType === "TIMESTAMP"
				? (this.toUserTimeZoneTimestamp(value) || value)
				: value;
			$($($field.children()[0]).children()[0]).val(displayValue);
		} else {
			$field.val(value);
		}
	}

	this.getBooleanValue = function($field) {
	    var value = null;
	    if($field.val() === 'true') {
            value = true;
        } else if ($field.val() === 'false') {
            value = false;
        } else {
            value = null;
        }
        return value;
	}

	this.getFieldValue = function(propertyType, $field) {
		var propertyTypeValue;
		if (propertyType.dataType === "BOOLEAN") {
		    propertyTypeValue = this.getBooleanValue($field);
		} else {
			propertyTypeValue = $field.val();
		}
		return propertyTypeValue;
	}
	
	//
	// Form Fields
	//
	this._getBoolean2Field = function(id, alt, isRequired) {
		var $dropdown = this.getDropDownForTerms(id, [
		    { code : "true", label : "true" },
		    { code : "false", label : "false" }
		], alt, isRequired);
		$dropdown.refresh = function() {
		    Select2Manager.add($dropdown);
		}
		return $dropdown;
	}

	this._getBooleanField = function(id, alt, checked, isRequired) {
		var attr = {'type' : 'checkbox', 'alt' : alt, 'placeholder' : alt };
		if(checked) {
			attr['checked'] = '';
		}
		if (id) {
            attr['id'] = this.prepareId(id);
        }

		var $container = $('<div>', {'class' : 'checkbox'}).append($('<label>').append($('<input>', attr)));

        if(alt) {
            $container.append($("<span>", { class: "glyphicon glyphicon-info-sign" })).append(alt ? " " + alt : "");
        }

		if (isRequired) {
            $container.attr('required', '');
        }

        return $container;
	}
	
	this.getDropDownForTerms = function(id, terms, alt, isRequired) {
		return this._getDropDownFieldForVocabulary(id, terms, alt, isRequired);
	}

	this._getDropDownFieldForVocabulary = function(code, terms, alt, isRequired) {
	    return this._getDropDownFieldForVocabulary(code, terms, alt, isRequired, false);
	}
	
	this._getDropDownFieldForVocabulary = function(code, terms, alt, isRequired, isMultiValue) {
	    var $component = $("<select>", {'placeholder' : alt, 'class' : 'form-control'});
	    if(isMultiValue) {
	        $component.attr('multiple', 'multiple');
	    }
		$component.attr('id', this.prepareId(code));
		
		if (isRequired) {
			$component.attr('required', '');
		}
		var $options = [];

		var properties = {
			placeholder: alt,
			allowClear: true
		}

		if(isMultiValue) {
			properties.closeOnSelect = false;
		}

		for(var i = 0; i < terms.length; i++) {
		    var $option = $("<option>", { value : terms[i].code }).text(terms[i].label);
			$options.push($option);
		}
		$component.append($options);
		Select2Manager.add($component, properties);
		$component.refresh = function() {
		    Select2Manager.add($component, properties);
		}
		return $component;
	}
	
	this.getTextInputField = function(id, alt, isRequired) {
		return this._getInputField('text', id, alt, null, isRequired);
	}
	
	this.getRealInputField = function(id, alt, isRequired) {
		return this._getInputField('text', id, alt, 0.01, isRequired);
	}
	
	this.getIntegerInputField = function(id, alt, isRequired) {
		return this._getInputField('text', id, alt, 1, isRequired);
	}
	
	this._getNumberInputField = function(id, alt, step, isRequired)
	{
		var $component = this._getInputField("number", id, alt, step, isRequired);
		var validator = function(event) {
			var target = event.target;
			if (!target.checkValidity()) {
				Util.showError("Not a valid number in field '" + target.alt + "'.",
						function() {
							Util.unblockUI();
							target.focus();
						});
			}
		};
		$component.blur(validator);
		return $component;
	}
	
	this._getInputField = function(type, id, alt, step, isRequired) {
		var $component = $('<input>', {'type' : type, 'id' : this.prepareId(id), 'alt' : alt, 'placeholder' : alt, 'class' : 'form-control'});
		if (isRequired) {
			$component.attr('required', '');
		}
		if (step) {
			$component.attr('step', step);
		}
		return $component;
	}
	
    this._getTextBox = function(id, alt, isRequired) {
		var $component = $('<textarea>', {'id' : id, 'alt' : alt, 'style' : 'height: 80px; width: 450px;', 'placeholder' : alt, 'class' : 'form-control'});
		if (isRequired) {
			$component.attr('required', '');
		}
		return $component;
	}

	this._getDiv = function(id, alt, isRequired) {
        var $component = $('<div>', {'id' : id, 'alt' : alt, 'placeholder' : alt});
        if (isRequired) {
            $component.attr('required', '');
        }
        return $component;
    }

	this._getDatePickerField = function(id, alt, isRequired, isDateOnly, value, excludeTimeZone) {
		// Multi-value date/timestamp: the ELN date picker is single-value; use the first element.
		if (Array.isArray(value)) {
			value = value.length > 0 ? value[0] : null;
		}
		var $component = $('<div>', {'class' : 'form-group', 'style' : 'margin-left: 0px;', 'placeholder' : alt, 'id' : 'datetimepicker_parent_' + id });
		var $subComponent = $('<div>', {'class' : 'input-group date', 'id' : 'datetimepicker_' + id });
		var $input = $('<input>', {'class' : 'form-control', 'type' : 'text', 'id' : id, 'placeholder' : (isDateOnly ? 'yyyy-MM-dd (YEAR-MONTH-DAY)' : (excludeTimeZone ? 'yyyy-MM-dd HH:mm:ss (YEAR-MONTH-DAY HOUR:MINUTE:SECOND)' : 'yyyy-MM-dd HH:mm:ss ZZ (YEAR-MONTH-DAY HOUR:MINUTE:SECOND TIMEZONE)')),
			'data-format' : isDateOnly ? 'yyyy-MM-dd' : 'yyyy-MM-dd HH:mm:ss'});
		if (isRequired) {
			$input.attr('required', '');
			$component.attr('required', '');
		}
		var $spanAddOn = $('<span>', {'class' : 'input-group-addon'})
							.append($('<span>', {'class' : 'glyphicon glyphicon-calendar' }));

		$subComponent.append($input);
		$subComponent.append($spanAddOn);

		var date = null;
		if(value) {
			if (!isDateOnly) {
				value = this.toUserTimeZoneTimestamp(value) || value;
			}
			date = Util.parseDate(value);
		}
		$subComponent.datetimepicker({
            format: isDateOnly ? 'YYYY-MM-DD' : (excludeTimeZone ? 'YYYY-MM-DD HH:mm:ss' : 'YYYY-MM-DD HH:mm:ss ZZ'),
            extraFormats: isDateOnly ? [] : [ 'YYYY-MM-DD HH:mm:ss' ],
            useCurrent: false,
            defaultDate: date,
            locale: 'en-GB',
        });

		$component.append($subComponent);

		$component.refresh = function() {
			$subComponent.datetimepicker({
				format : isDateOnly ? 'YYYY-MM-DD' : (excludeTimeZone ? 'YYYY-MM-DD HH:mm:ss' : 'YYYY-MM-DD HH:mm:ss ZZ'),
				extraFormats : isDateOnly ? [] : [ 'YYYY-MM-DD HH:mm:ss' ],
				useCurrent : false,
				defaultDate : $input.val().trim() ? date : false,
			});
		}

		return $component;
	}

    this.ckEditor4to5ImageStyleMigration = function(value) {
        var buffer = "";
        var offset = 0;

        while(offset < value.length) {
            currentImageStartOffset = -1;
            currentImageEndOffset = -1;
            styleTag = null;

            currentImageStartOffset = value.indexOf("<img", offset);
            if(currentImageStartOffset !== -1) {
                currentImageEndOffset = value.indexOf(">", currentImageStartOffset);
            }

            if(currentImageStartOffset !== -1 && currentImageEndOffset !== -1) {
                currentStyleStartOffset = null;
                currentStyleEndOffset = null;

                currentStyleStartOffset = value.indexOf("style=\"", currentImageStartOffset);
                if(currentStyleStartOffset !== -1) {
                    currentStyleEndOffset = value.indexOf("\"", currentStyleStartOffset + "style=\"".length);
                }

                if(currentStyleStartOffset !== -1 && currentStyleEndOffset !== -1) {
                    styleTag = value.substring(currentStyleStartOffset, currentStyleEndOffset + "\"".length);
                }
            }

            // Move offset
            if(currentImageEndOffset !== -1) {
                buffer = buffer + value.substring(offset, currentImageStartOffset);
                if(styleTag !== null) {
                    buffer = buffer + "<figure class=\"image image_resized\"" + styleTag + ">";
                }
                buffer = buffer + value.substring(currentImageStartOffset, currentImageEndOffset + ">".length);
                if(styleTag !== null) {
                    buffer = buffer + "</figure>";
                }
                offset = currentImageEndOffset + ">".length;
            } else {
                buffer = buffer + value.substring(offset, value.length);
                offset = value.length;
            }
        }

        return buffer;
    }

    this.createCkeditor = function($component, componentOnChange, value, placeholder, isReadOnly, toolbarContainer, _refreshableFields) {
        // Multi-value Word Processor: value is an array of HTML strings; join for display.
        if (Array.isArray(value)) {
            value = value.filter(function(v) { return v != null && v !== ''; }).join('<hr>');
        }

        // CKEditor 4 to 5 Image style Migration
        if( value &&
            value.indexOf("<img")  !== -1 &&
            value.indexOf("<figure") === -1) {
            value = this.ckEditor4to5ImageStyleMigration(value);
        }

        var ids = [];
        if(isReadOnly && value) {
            var identifierRegexp = /(?:\/[A-Z_\d]+){3,5}/g
            ids = value.match(identifierRegexp);
            if (!ids) {
                ids = [];
            }
            var permIdRegexp = /\d{17}-\d+/g
            var permIds = value.match(permIdRegexp);
            if ( !permIds) {
                permIds = [];
            }
            ids = ids.concat(permIds);
        }
	    var Builder = null;
// CK Editor 34
//	    if(toolbarContainer) {
//            Builder = InlineEditor.DecoupledEditor;
//	    } else {
//	        Builder = InlineEditor.InlineEditor;
//	    }

        // CK Editor 18
	    if(toolbarContainer) {
            Builder = CKEDITOR.DecoupledEditor;
	    } else {
	        Builder = CKEDITOR.InlineEditor;
	    }
        Builder.create($component[0], {
                         placeholder: placeholder,
                         simpleUpload: {
                             uploadUrl: "/openbis/openbis/file-service/eln-lims?type=Files&sessionID=" + mainController.serverFacade.getSession()
                         }
                    })
                    .then( editor => {
                        editor.acceptedData = ""; // Is used to undo paste events containing images coming from a different domain
						const modeFeatureId = 'editor-mode';

                        if (value) {
                            editor.preprocessingFinished = false;
                            if(isReadOnly && ids.length > 0)
                            {
                                this._searchByIds(ids, function(checkedLinks) {
                                    // Replace identifiers/permIds with links to forms. Just .replace wont work because some identifiers could be a subset of others, e.g /X/X/X is a subset of /X/X/X_EXP_1
                                    let arrayOfMatchedIds = [];
                                    for(let l in checkedLinks) {
                                        let re = new RegExp(l+"\\b", 'g');
                                        while ((match = re.exec(value)) != null) {
                                            arrayOfMatchedIds.push({index: match.index, value: l, href: checkedLinks[l].link, identifier: checkedLinks[l].identifier});
                                        }
                                    }
                                    arrayOfMatchedIds = arrayOfMatchedIds.sort((a,b) => a.index - b.index);
                                    var ind = 0;
                                    var existingLinksRegExp = /<a href="(.*?)">|(www|http:|https:)+[^\s]+[\w]/g
                                    while ((match = existingLinksRegExp.exec(value)) != null) {
                                        arrayOfMatchedIds = arrayOfMatchedIds.filter(matchedId => !(match.index < matchedId.index && match.index + match[0].length > matchedId.index));
                                    }
                                    for(let matchedId of arrayOfMatchedIds) {
                                        // </span> is a hack to display links as proper links in CKEditor
                                        var newLink = '</span>' + checkedLinks[matchedId.value].link[0].outerHTML
                                                                    .replace('class="browser-compatible-javascript-link"', '')
                                                                    .replace('>' + matchedId.identifier + '<', '>' + checkedLinks[matchedId.value].name + '<')
                                               + '<span style="background-color:rgb(255,255,255);color:rgb(51,51,51);font-size:14px;">';
                                        newLink = decodeURIComponent(newLink);
                                        value = value.substring(0, matchedId.index + ind) + newLink + value.substring(matchedId.index + ind + matchedId.value.length, value.length);
                                        ind += newLink.length - matchedId.value.length;
                                    }

									editor.disableReadOnlyMode(modeFeatureId);
                                    editor.setData(value);
                                    editor.acceptedData = editor.getData();

                                    var root = editor.editing.view.getDomRoot();
                                    for(let l in checkedLinks){
                                         let links = $(root).find('a[href]')
                                                .filter((x, y) => y.text === checkedLinks[l].name);

                                         links.attr('href', "javascript:void(0)")
                                                .click(function() {
                                                    checkedLinks[l].link.click();
                                                });
                                         links.refresh = function() {
                                            this.unbind();
                                            this.click(function() {
                                                checkedLinks[l].link.click();
                                            });
                                         }
                                         if(_refreshableFields) {
                                            _refreshableFields.push(links);
                                         }

                                    }
                                    editor.preprocessingFinished = true;
									editor.enableReadOnlyMode(modeFeatureId);
                                });

                            } else {
                                editor.preprocessingFinished = true;
                                value = this.prepareCkeditorData(value);
                                editor.setData(value);
                                editor.acceptedData = editor.getData();
                            }
                        }

						if (isReadOnly) {
							editor.enableReadOnlyMode(modeFeatureId);
						} else {
							editor.disableReadOnlyMode(modeFeatureId);
						}
                        editor.model.document.on('change:data', function (event, data) {
                            var newData = editor.getData();
                            var preprocessing = editor.preprocessingFinished ?? true;
                            if(preprocessing && newData !== editor.acceptedData) {
                                var isDataValid = CKEditorManager.isDataValid(newData);
                                if(isDataValid) {
                                    editor.acceptedData = newData;
                                    if(componentOnChange) {
                                        componentOnChange(event, newData); // Store changes on original model
                                    }
                                } else {
                                    editor.setData(editor.acceptedData);
                                    Util.showUserError("It is not possible to copy an image directly from a website.");
                                }
                            }
                        });

                        if(toolbarContainer) {
                            toolbarContainer.append(editor.ui.view.toolbar.element);
                        }

                        CKEditorManager.addEditor($component.attr('id'), editor);

//                        $component.on('paste', function(evt) {
//                            evt.stop(); // we don't let editor to paste data;
//                            alert('paste');
//                        });
                    })
                    .catch(error => {
                        Util.showError(error);
                    });
	}


	this._searchByIds = function(identifiers, callback) {
	    //search Experiments and Samples by a would-be identifiers and returns links to them
        require([ "as/dto/sample/id/SampleIdentifier", "as/dto/sample/id/SamplePermId", "as/dto/sample/fetchoptions/SampleFetchOptions",
         "as/dto/experiment/id/ExperimentIdentifier", "as/dto/experiment/id/ExperimentPermId", "as/dto/experiment/fetchoptions/ExperimentFetchOptions"],
                    function(SampleIdentifier, SamplePermId, SampleFetchOptions, ExperimentIdentifier, ExperimentPermId, ExperimentFetchOptions) {
                        var sampleFetchOptions = new SampleFetchOptions();
                        sampleFetchOptions.withProperties();
                        var ids = identifiers.map(id => {
                            if(id.startsWith('/')) {
                                return new SampleIdentifier(id);
                            }
                            return new SamplePermId(id);
                        });

                        mainController.openbisV3.getSamples(ids, sampleFetchOptions).done(function(sampleResults) {
                            let links = {};
                            let missing = []
                            var samples = Util.mapValuesToList(sampleResults);
                            for ( let sample of samples) {
                                if(identifiers.includes(sample.permId.permId)) {
                                    identifiers = identifiers.filter(x => x != sample.permId.permId);
                                } else if(identifiers.includes(sample.identifier.identifier)) {
                                    identifiers = identifiers.filter(x => x != sample.identifier.identifier);
                                }
                                var link = FormUtil.getFormLink(sample.identifier.identifier, 'Sample', sample.permId.permId, null);
                                var name = sample.properties['NAME'] ?? null;
                                name = sample.identifier.identifier + (name ? ' (' + name + ')' : '');
                                links[sample.identifier.identifier] = {link: link, name: name, identifier: sample.identifier.identifier};
                                links[sample.permId.permId] = {link: link, name: name, identifier: sample.identifier.identifier};
                            }
                            if(identifiers.length == 0) {
                                callback(links);
                            } else {
                                var experimentFetchOptions = new ExperimentFetchOptions();
                                experimentFetchOptions.withProperties();
                                var ids = identifiers.map(id => {
                                    if(id.startsWith('/')) {
                                        return new ExperimentIdentifier(id);
                                    }
                                    return new ExperimentPermId(id);
                                });

                                mainController.openbisV3.getExperiments(ids, experimentFetchOptions).done(function(experimentResults) {
                                    var experiments = Util.mapValuesToList(experimentResults);
                                    for ( let experiment of experiments) {
                                        var link = FormUtil.getFormLink(experiment.identifier.identifier, 'Experiment', experiment.identifier.identifier, null);
                                        var name = experiment.properties['NAME'] ?? null;
                                        name = experiment.identifier.identifier + (name ? ' (' + name + ')' : '');
                                        links[experiment.identifier.identifier] = {link: link, name: name, identifier: experiment.identifier.identifier};
                                        links[experiment.permId.permId] = {link: link, name: name, identifier: experiment.identifier.identifier };
                                    }
                                    callback(links);
                                }).fail(function(result) {
                                    callback(links);
                                });
                            }
                        }).fail(function(result) {
                            callback({});
                        });
                    });
    }

	this.prepareCkeditorData = function(value) {
	    value = value.replace(/(font-size:\d+\.*\d+)pt/g, "$1" + "px"); // https://ckeditor.com/docs/ckeditor5/latest/features/font.html#using-numerical-values
	    return value;
	}

	this.activateRichTextProperties = function($component, componentOnChange, propertyType, value, isReadOnly, toolbarContainer, _refreshableFields) {
		// InlineEditor is not working with textarea that is why $component was changed on div
	    var placeholder = propertyType ? propertyType.description : "";
		var $component = this._getDiv($component.attr('id'), $component.attr('alt'), $component.attr('isRequired'));
		if(!$component.attr('id')) {
		    $component.attr('id', 'ckEditor-' + mainController.getNextId());
		}
		FormUtil.createCkeditor($component, componentOnChange, value, placeholder, isReadOnly, toolbarContainer, _refreshableFields);

		if (propertyType && propertyType.mandatory) {
			$component.attr('required', '');
		}

		$component.refresh = function() {
		    var instance = CKEditorManager.getEditorById($component.attr("id"));
			if(!instance) {
				let newValue = $component.html();
				FormUtil.createCkeditor($component, componentOnChange, newValue, placeholder, isReadOnly, toolbarContainer);
			}
		}
		return $component;
	}
	
	this.fixStringPropertiesForForm = function(propertyType, entity) {
	    if(entity) {
            var originalValue = entity.properties[propertyType.code];
            if(propertyType.metaData["custom_widget"] && propertyType.metaData["custom_widget"] === "Word Processor" && originalValue) { // Only filter properties rendered as HTML
                entity.properties[propertyType.code] = this.sanitizeRichHTMLText(originalValue);
            }
		}
	}
	
	this.sanitizeRichHTMLText = function(originalValue) {
		if (typeof originalValue === "string") {
			//Take envelope out if pressent
			var bodyStart = originalValue.indexOf("<body>");
			var bodyEnd = originalValue.indexOf("</body>");
			if(bodyStart !== -1 && bodyEnd !== -1) {
				originalValue = originalValue.substring(bodyStart + 6, bodyEnd);
			}
			//Clean the contents
			//originalValue = html.sanitize(originalValue);
			originalValue = DOMPurify.sanitize(originalValue);
		}
		return originalValue;
	}

	this.addOptionsToToolbar = function($formColumn, toolbarModel, dropdownOptionsModel, hideShowOptionsModel, namespace, title, alignLeft) {
	    var _this = this;
		if(!title) {
			title = "More ... ";
		}
		var id = 'options-menu-btn-' + mainController.getNextId();
		if (namespace) {
		    id = id + "-" + namespace;
		    id = id.toLowerCase();
		}
		var $dropdownOptionsMenu = $("<span>", { class : 'dropdown' });
		if(toolbarModel) {
		    toolbarModel.push({ component : $dropdownOptionsMenu, tooltip: null });
		}
		var $dropdownOptionsMenuCaret = $("<a>", { 'href' : '#', 'data-toggle' : 'dropdown', class : 'dropdown-toggle btn btn-default', 'id' : id})
				.append(title).append($("<b>", { class : 'caret' }));
		var $dropdownOptionsMenuList = $("<ul>", { class : 'dropdown-menu', 'role' : 'menu', 'style' : "overflow-y: scroll; max-height: 64vh;" });
		if(alignLeft) {
		    $dropdownOptionsMenuList.css("right", "0").css("left", "auto");
		}
		$dropdownOptionsMenu.append($dropdownOptionsMenuCaret);
		$dropdownOptionsMenu.append($dropdownOptionsMenuList);
		for (var idx = 0; idx < dropdownOptionsModel.length; idx++) {
			var option = dropdownOptionsModel[idx];
			if(option.separator) {
				$dropdownOptionsMenuList.append($("<li>", { 'role' : 'presentation' }).append($("<hr>", { style : "margin-top: 5px; margin-bottom: 5px;"})));
			} else {
				var label = option.label;
				var title = option.title ? option.title : label;
				var id = _this.prepareId(title).toLowerCase() + "-" +  + mainController.getNextId();
				var $dropdownElement = $("<li>", { 'role' : 'presentation' }).append($("<a>", {'title' : title, 'id' : id}).append(label));
				option.view = $dropdownElement;
				if(option.hidden) {
					$dropdownElement.attr("hidden", "hidden");
				}
				$("body").off("click", "[id='"+id+"']");
                $("body").on("click", "[id='"+id+"']", option.action);
				$dropdownOptionsMenuList.append($dropdownElement);
			}
		}

		if(hideShowOptionsModel.length > 0 && dropdownOptionsModel.length > 0) {
			$dropdownOptionsMenuList.append($("<li>", { 'role' : 'presentation' }).append($("<hr>", { style : "margin-top: 5px; margin-bottom: 5px;"})));
		}

		var settingsKey = namespace + "-showing-sections";
		mainController.serverFacade.getSetting(settingsKey, function(settingsValue) {
			var sectionsSettings = settingsValue ? JSON.parse(settingsValue) : {};
			for (var idx = 0; idx < hideShowOptionsModel.length; idx++) {
				var option = hideShowOptionsModel[idx];
				var shown = option.forceToShow === true;
				if (shown === false) {
					var sectionSetting = sectionsSettings[option.label];
					if (sectionSetting !== undefined) {
						shown = sectionSetting === 'shown';
					} else if (option.showByDefault) {
						shown = true;
					} else {
						shown = ! profile.hideSectionsByDefault;
					}
				}
				var $section;
				if($formColumn) {
					$section = $formColumn.find(option.section);
				} else {
					$section = $(option.section);
				}

				$section.toggle(shown);
				var $label = $("<span>").append((shown ? "Hide " : "Show ") + option.label);
				var id = 'options-menu-btn-' + _this.prepareId(option.label).toLowerCase() + '-' + mainController.getNextId();
				var $dropdownElement = $("<li>", { 'role' : 'presentation' }).append($("<a>", { 'id' : id }).append($label));
				var action = function(event) {
					var option = event.data.option;
					var $label = event.data.label;
					var $section = $(event.data.section);
					$section.toggle(300, function() {
						if ($section.css("display") === "none") {
							$label.text("Show " + option.label);
							sectionsSettings[option.label] = "hidden";
						} else {
							if (option.beforeShowingAction) {
								option.beforeShowingAction();
							}
							$label.text("Hide " + option.label);
							sectionsSettings[option.label] = "shown";
						}
						$(window).trigger('resize'); // HACK: Fixes table rendering issues when refreshing the grid on fuelux 3.1.0 for all browsers
						mainController.serverFacade.setSetting(settingsKey, JSON.stringify(sectionsSettings));
						if(option.refresh) {
						    option.refresh();
						}
					});
				};
				$("body").off("click", "[id='"+id+"']");
                $("body").on("click", "[id='"+id+"']", {option : option, label : $label, section : $section}, action);
				$dropdownOptionsMenuList.append($dropdownElement);
			}
		});
	}
	
	this.getToolbar = function(toolbarModel) {
		var $toolbarContainer = $("<span>", { class : 'toolBox' });
		
		for(var tbIdx = 0; tbIdx < toolbarModel.length; tbIdx++) {
			var $toolbarComponent = toolbarModel[tbIdx].component;
			var toolbarComponentTooltip = toolbarModel[tbIdx].tooltip;
			var $toolbarComponentTooltip = toolbarModel[tbIdx].$tooltip;
			if(toolbarComponentTooltip) {
				$toolbarComponent.attr("title", toolbarComponentTooltip);
				$toolbarComponent.tooltipster();
			} else if ($toolbarComponentTooltip) {
				$toolbarComponent.tooltipster({
					content: $toolbarComponentTooltip
				});
			}
			$toolbarContainer.append($toolbarComponent);
			$toolbarContainer.append("&nbsp;");
		}
		
		return $toolbarContainer;
	}

	this.getToolbarSeparator = function() {
	    var separator = $("<p>", {id : "toolbar-separator"})
        		                    .css("display", "inline-block")
        separator.html("&nbsp&nbsp&nbsp&nbsp&nbsp");
	    return separator;
	}

	this.getToolbarWithTabs = function(
		toolbarModel,
		tabsModel,
		rightToolbarModel,
		extraToolbar, 
		alternateToolbar,
		$alternateRightToolbar
	  ) {		
		var $normalToolbar = this.getToolbar(toolbarModel);
		var $rightToolbarButtons = this.getToolbar(rightToolbarModel);		
		$rightToolbarButtons.css({ marginBottom: "0px" });	
		$alternateRightToolbar.css({ marginBottom: "0px" });	
		
		var containerId = tabsModel.containerId || "";
		var toolbarId = tabsModel.toolbarId || "toolbar-id" + mainController.getNextId();
		var tabs = tabsModel.tabs || [];
		var tabsContainerOptions = { 
		  class: "nav nav-tabs toolbar-tabs", 
		  style: "border-bottom: 0; margin: 0; padding: 0; display: flex;"
		};
		if (containerId) {
		  tabsContainerOptions.id = containerId;
		}
		var $tabsContainer = $("<ul>", tabsContainerOptions);
		tabs.forEach(function(tab) {
		  var liClass = tab.active ? "active" : "";
		  var $li = $("<li>", { class: liClass, style: "margin-bottom: -15px;" });
		  var aOptions = {
			href: tab.href,
			"data-toggle": "tab",
			text: tab.label
		  };
		  if (tab.id) {
			aOptions.id = tab.id;
		  }
		  var $a = $("<a>", aOptions);
		  $li.append($a);
		  $tabsContainer.append($li);
		});

		var $normalToolbarContainer = $("<div>", { class: "normal-toolbar-container" })
		  .css({ flex: "1" })
		  .append($normalToolbar);
		var $alternateToolbarContainer = $("<div>", { class: "alternate-toolbar-container" })
		  .css({ flex: "1" })
		  .append(alternateToolbar);

		$alternateToolbarContainer.hide();

		var $buttonsWrapper = $("<div>", { class: "toolbar-buttons" })
		  .css({
			width: $rightToolbarButtons.children().length > 0 ? "50%" : "100%",
			display: "flex"
		  });
		$buttonsWrapper.append($normalToolbarContainer).append($alternateToolbarContainer);
	  
		var $normalRightToolbarContainer = $("<div>", { class: "normal-right-toolbar-container" })
		  .css({ flex: "1" })
		  .append($rightToolbarButtons);
				
		var $extraRightToolbarContainer = $("<div>", { class: "extra-right-toolbar-container" })
		  .css({
			display: "flex",
			alignItems: "center",
			gap: "10px"
		  }).append(extraToolbar);
		
		$extraRightToolbarContainer.hide();

		var $alternateRightToolbarContainer = $("<div>", { class: "alternate-right-toolbar-container" })
		  .css({
			display: "flex",
			alignItems: "baseline",
			gap: "10px",
			height: "34px"
		  }).append($alternateRightToolbar);
		$alternateRightToolbarContainer.hide();
	  
		var $rightSideContainer = $("<div>", { class: "right-side-container" }).css({
		  display: "flex",
		  alignItems: "center",		  
		});
	  		
		$rightSideContainer
		  .append($normalRightToolbarContainer)
		  .append($extraRightToolbarContainer)
		  .append($alternateRightToolbarContainer)
		  .append($tabsContainer);
	  
		var $combinedContainer = $("<div>", { id: toolbarId, class: "toolbar-with-tabs" }).css({
		  display: "flex",
		  alignItems: "center",
		  justifyContent: "space-between",
		  width: "100%",
		  minHeight: "37px",
		});
		$combinedContainer.append($buttonsWrapper).append($rightSideContainer);
		
		return $combinedContainer;
	  };


		
	
