    this.archivingAfsDataSectionButtons = function(permId, buttonsContainer) {
        var _this = this;

        var $buttons = $('<div>', {'id' : 'archiving_buttons-' + permId})
                            .css({
                                display: "flex",
                            });
        if(buttonsContainer) {
            $buttons = buttonsContainer;
        }


        var archiveForm = function(dataset, container) {
            var physicalData = null;
            if(dataset) {
                physicalData = dataset.physicalData;
            }

            if(physicalData) {

                var archiveIcon = "ARCHIVE_NOT_REQUESTED";
                var archiveImage = "./img/archive-not-requested-icon.png";
                var archiveStatus = physicalData.status;
                if (physicalData.presentInArchive) {
                    archiveIcon = "ARCHIVED";
                    archiveImage = "./img/archive-archived-icon.png";
                    archiveStatus = "ARCHIVED";
                    if(physicalData.unarchivingRequested && physicalData.status == "ARCHIVED"){
                        archiveIcon = "UNARCHIVE_REQUESTED";
                    }
                } else if (physicalData.archivingRequested || physicalData.status == "ARCHIVE_PENDING") {
                    archiveImage = "./img/archive-requested-icon.png";
                    archiveIcon = "ARCHIVE_REQUESTED";
                    if(physicalData.archivingRequested) {
                        archiveStatus = "ARCHIVE REQUESTED";
                    } else {
                        archiveStatus = "ARCHIVE PENDING";
                    }
                }
                var iconType = IconUtil.getToolbarIconType(archiveIcon)
                var icon = IconUtil.getIcon(iconType);
                icon.css('margin-left', '-2px')

                var archiveTooltip = null;
                if (physicalData.status == "AVAILABLE") {
					if(physicalData.presentInArchive){
						var $message = FormUtil.getToolbarButton("ARCHIVED")
						$message.attr("disabled", "disabled");
						$message.append('&nbsp;')
						$message.append("Unarchived");
						container.append($message)
					} else {
						if (physicalData.archivingRequested) {
							var $revokeButton = $('<div>', {'class' : 'btn btn-primary btn-secondary', 'id' : 'revoke-archiving-btn-'+permId});
							$revokeButton.append(icon)
							$revokeButton.append('&nbsp;')
							$revokeButton.append('Revoke archiving request')
							$("body").off('click', '#revoke-archiving-btn-'+permId);
							$("body").on('click', '#revoke-archiving-btn-'+permId, function() {
								var physicalDataUpdate = { archivingRequested : false }
								mainController.serverFacade.updateDataSet(permId, physicalDataUpdate, function() {
									container.empty();
									FormUtil.archivingAfsDataSectionButtons(permId, container);
									Util.unblockUI();
									Util.showSuccess("Archive request revoked");
								});
							});
							container.append($revokeButton).append('&nbsp;')
							archiveTooltip = "Revoke archiving request";
						} else {
							var $requestButton = $('<div>', {'class' : 'btn btn-primary btn-secondary', 'id' : 'request-archiving-btn-'+permId});
							$requestButton.append(icon)
							$requestButton.append('&nbsp;')
							$requestButton.append('Request archiving')
							$("body").off('click', '#request-archiving-btn-'+permId);
							$("body").on('click', '#request-archiving-btn-'+permId, function() {
								Util.requestArchiving([dataset], function() {
									container.empty();
									FormUtil.archivingAfsDataSectionButtons(permId, container);
									Util.unblockUI();
								});
							});

							var iconTypeLocked = IconUtil.getToolbarIconType("LOCK")
							var iconLocked = IconUtil.getIcon(iconTypeLocked);
							iconLocked.css('margin-left', '-2px')

							var $lockButton = $('<div>', {'class' : 'btn btn-primary btn-secondary', 'id' : 'lock-archiving-btn-'+permId});
							$lockButton.append(iconLocked)
							$lockButton.append('&nbsp;')
							$lockButton.append('Disallow archiving')
							$("body").off('click', '#lock-archiving-btn-'+permId);
							$("body").on('click', '#lock-archiving-btn-'+permId, function() {
								var physicalDataUpdate = { status : "LOCKED" }
								mainController.serverFacade.updateDataSet(permId, physicalDataUpdate, function() {
									container.empty();
									FormUtil.archivingAfsDataSectionButtons(permId, container);
									Util.unblockUI();
									Util.showSuccess("Archiving Locked");
								});
							});
							container.append($requestButton).append('&nbsp;').append($lockButton).append('&nbsp;')
							archiveTooltip = "Request or disallow archiving";
						}
					}
                } else if (physicalData.status == "LOCKED") {
                    var $allowArchivingButton = $('<div>', {'class' : 'btn btn-primary btn-secondary', 'id' : 'unlock-archiving-btn-'+permId});
                    var iconTypeUnlock = IconUtil.getToolbarIconType("UNLOCK")
                    var iconUnlock = IconUtil.getIcon(iconTypeUnlock);
                    iconUnlock.css('margin-left', '-2px')
                    $allowArchivingButton.append(iconUnlock)
                    $allowArchivingButton.append('&nbsp;')
                    $allowArchivingButton.append('Allow archiving')
                    $("body").off('click', '#unlock-archiving-btn-'+permId);
                    $("body").on('click', '#unlock-archiving-btn-'+permId, function() {
                      var physicalDataUpdate = { status : "AVAILABLE" }
                      mainController.serverFacade.updateDataSet(permId, physicalDataUpdate, function() {
                          container.empty();
                          FormUtil.archivingAfsDataSectionButtons(permId, container);
                          Util.unblockUI();
                          Util.showSuccess("Archiving Unlocked");
                      });
                    });
                    container.append($allowArchivingButton).append('&nbsp;')
                    archiveTooltip = "Allow archiving";
                } else if (physicalData.status == "ARCHIVED") {
					if (physicalData.unarchivingRequested) {
							var $revokeButton = $('<div>', {'class' : 'btn btn-primary btn-secondary', 'id' : 'revoke-unarchiving-btn-'+permId});
							$revokeButton.append(icon)
							$revokeButton.append('&nbsp;')
							$revokeButton.append('Revoke unarchiving request')
							$("body").off('click', '#revoke-unarchiving-btn-'+permId);
							$("body").on('click', '#revoke-unarchiving-btn-'+permId, function() {
								var physicalDataUpdate = { unarchivingRequested : false }
								mainController.serverFacade.updateDataSet(permId, physicalDataUpdate, function() {
									container.empty();
									FormUtil.archivingAfsDataSectionButtons(permId, container);
									Util.unblockUI();
									Util.showSuccess("Unarchive request revoked");
								});
							});
							container.append($revokeButton).append('&nbsp;')
							archiveTooltip = "Revoke unarchiving request";
					} else {
						var $unarchiveButton = $('<div>', {'class' : 'btn btn-primary btn-secondary', 'id' : 'request-unarchiving-btn-'+permId});
						$unarchiveButton.append(icon)
						$unarchiveButton.append('&nbsp;')
						$unarchiveButton.append('Request unarchiving')
						$("body").off('click', '#request-unarchiving-btn-'+permId);
						$("body").on('click', '#request-unarchiving-btn-'+permId, function() {
							mainController.serverFacade.unarchiveDataSets([permId], function(result){
								if(result){
									container.empty();
									FormUtil.archivingAfsDataSectionButtons(permId, container);
									Util.unblockUI();
								}
							});
						});
						container.append($unarchiveButton).append('&nbsp;')
						archiveTooltip = "Request unarchiving";
					}
                } else if (physicalData.status == "ARCHIVE_PENDING") {
					var $message = FormUtil.getToolbarButton("ARCHIVE_REQUESTED")
					$message.attr("disabled", "disabled");
					$message.append('&nbsp;')
					$message.append("Archiving pending");
					container.append($message)
				} else if (physicalData.status == "UNARCHIVE_PENDING") {
					var $message = FormUtil.getToolbarButton("ARCHIVE_REQUESTED")
					$message.attr("disabled", "disabled");
					$message.append('&nbsp;')
					$message.append("Unarchiving pending");
					container.append($message)
				}
            }

        }

        require([ "as/dto/dataset/id/DataSetPermId", "as/dto/dataset/fetchoptions/DataSetFetchOptions" ],
            function(DataSetPermId, DataSetFetchOptions) {
                var ids = [new DataSetPermId(permId)];
                var fetchOptions = new DataSetFetchOptions();
                fetchOptions.withPhysicalData();
                mainController.openbisV3.getDataSets(ids, fetchOptions).done(function(map) {
                    var datasets = Util.mapValuesToList(map);
                    archiveForm(datasets.length > 0 ? datasets[0] : null, $buttons)
                });
        });
        return $buttons;
    }

    this.showFreezeAfsDataForm = function(entityType, permId, code) {
        var _this = this;

        Util.blockUI();

        var $window = $('<form>', {
        					'action' : 'javascript:void(0);'
        				});

        $window.append($('<legend>')
        				    .append("Freeze Entity data of")
        				    .append("&nbsp;")
        				    .append(code)
        				    .append("&nbsp;")
        				    .append($("<span>", { class: "material-icons", text: "warning_amber", style: "font-size: 26px; vertical-align: text-bottom;" }))
                            .append($("<span>", { style : "color:red; font-size: large;" })
                            .append(" This operation is irreversible!"))
        				);

        //todo list child entities?

        //
        // Warning
        //
        var operationMin = 0;
        var operationMax = 100;
        var operationNumberOne = Math. floor(Math. random() * (operationMax - operationMin + 1)) + operationMin;
        var operationNumberTwo = Math. floor(Math. random() * (operationMax - operationMin + 1)) + operationMin;
        var operationOperand = Math.random() < 0.5; // 50% provability of getting true
        var operationResult = (operationOperand)?operationNumberOne+operationNumberTwo:operationNumberOne-operationNumberTwo;
        var confirmationText = operationNumberOne + ' ' + ((operationOperand)?'+':'-') + ' ' + operationNumberTwo + ' = ?';

        $window.append("<br>");
        $window.append($("<p>")
                .append($("<span>", { class: "material-icons", text: "info_outline", style: "font-size: 20px; vertical-align: bottom;" }))
                .append(" Write the result to '" + confirmationText + "' on the confirmation field, after data is frozen no more changes will be possible:"));

        //
        // Password
        //
        var $passField = FormUtil._getInputField('input', "CODE_FREEZE_FIELD", confirmationText , null, true);
        var $passwordGroup = FormUtil.getFieldForComponentWithLabel($passField, "Operation Result", null);
        $window.append($passwordGroup);

        //
        // Buttons
        //
        var $btnAccept = $('<input>', { 'type': 'submit', 'class' : 'btn btn-primary', 'value' : 'Accept' });

        var $btnCancel = $('<a>', { 'class' : 'btn btn-default' }).append('Cancel');
        $btnCancel.click(function() {
            Util.unblockUI();
        });

        $window.append($('<br>'));

        $window.append($btnAccept).append('&nbsp;').append($btnCancel);

        $window.submit(function() {

            var password = $passField.val();
            if(password != operationResult) {
                Util.showUserError('The given result is not correct.');
            } else {
                require([ "as/dto/experiment/update/ExperimentUpdate", "as/dto/experiment/id/ExperimentPermId",
                              "as/dto/sample/update/SampleUpdate", "as/dto/sample/id/SamplePermId"],
                    function(ExperimentUpdate, ExperimentPermId, SampleUpdate, SamplePermId) {
                        var doneFunction = function() {
                            Util.showSuccess("Freezing data succeeded.", function() {
                                Util.unblockUI();
                                switch(entityType) {
                                    case "SAMPLE":
                                        mainController.changeView('showViewSamplePageFromPermId', permId);
                                        break;
                                    case "EXPERIMENT":
                                        mainController.changeView('showExperimentPageFromPermId', permId);
                                        break;
                                }
                            });
                        }
                        var failFunction = function() {
                           Util.showUserError('Freezing data failed.', function() {
                               Util.unblockUI();
                           });
                        }
                        switch(entityType) {
                            case "SAMPLE":
                               var sampleUpdate = new SampleUpdate();
                               sampleUpdate.setSampleId(new SamplePermId(permId));
                               sampleUpdate.makeDataImmutable();
                               mainController.openbisV3.updateSamples( sampleUpdate ).done(doneFunction).fail(failFunction);
                               break;
                            case "EXPERIMENT":
                                var experimentUpdate = new ExperimentUpdate();
                                experimentUpdate.setExperimentId(new ExperimentPermId(permId))
                                experimentUpdate.makeDataImmutable();
                                mainController.openbisV3.updateExperiments([ experimentUpdate ]).done(doneFunction).fail(failFunction);
                                break;
                            default:
                                Util.showError("Unsupported entity type for this operation: " + entityType);
                        }
                    });
            }
            Util.unblockUI();
        });

        var css = {
                'text-align' : 'left',
                'top' : '15%',
                'width' : '70%',
//                'height' : '400px',
                'left' : '15%',
                'right' : '20%',
                'overflow' : 'none'
        };

        Util.blockUI($window, css, false, function() {
            const myInput = document.getElementById("CODE_FREEZE_FIELD");
            myInput.onpaste = e => e.preventDefault();
        });

    }

