	this._atLeastOnyEntitySelectedHasBeenSelectedForFreezing = function(entityMap) {
		for (key in entityMap) {
			if ($('#' + this._createFormFieldId(key))[0].checked) {
				return true;
			}
		}
		return false;
	}
	
	this._createFormFieldId = function(key) {
		return 'freezing-form-' + key.replace("+", "-").replace(/\./g, "-");
	}
	
	this.showFreezingError = function(error) {
		Util.showError(error.message);
	}

	this.prepareId = function(id) {
		if (id) {
			id = id[0] === '$' ? id.substring(1) : id;
			id = id.split(".").join("");
			id = id.split(" ").join("-").split("/").join("_");
			id = id.split("(").join("_").split(")").join("_");
		}
		return id;
	}

    this.renderBooleanGridValue = function(params) {
        if(params.value === null){
            return "(empty)"
        }else{
            return String(params.value)
        }
    }

    this.renderGridValue = function(params) {
        if(!params.value || params.value === null){
            return ""
        }else{
            if(Array.isArray(params.value)) {
                return params.value.toString();
            }
            return String(params.value)
        }
    }

	this.renderDateTimeGridValue = function(row, params, propertyType) {
		const value = row[propertyType.code]
		if (!value) {
			return ""
		}

		if (propertyType.dataType === "TIMESTAMP") {
			return this.toUserTimeZoneTimestamp(value);
		} else {
			return value;
		}
    }

	this.renderArrayGridValue = function(row, params, propertyType) {
		const value = row[propertyType.code]
		if (!value) {
			return ""
		}

        if (propertyType.dataType === "ARRAY_STRING") {
            return '[' + value.map(v => v == null ? 'null' : '"' + v + '"').join(', ') + ']';
        } else if (propertyType.dataType === "ARRAY_TIMESTAMP") {
            return '[' + value.map(v => v == null ? 'null' : '"' + this.toUserTimeZoneTimestamp(v) + '"').join(', ') + ']';
        } else {
			return '[' + value.map(v => v == null ? 'null' : v).join(', ') + ']';
		}
    }

    this.renderMultilineVarcharGridValue = function(row, params, propertyType){
        return this.renderCustomWidgetGridValue(row, params, propertyType)
    }

    this.renderXmlGridValue = function(row, params, propertyType){
        return this.renderCustomWidgetGridValue(row, params, propertyType)
    }

    this.renderCustomWidgetGridValue = function(row, params, propertyType){
        var value = row[propertyType.code]

        if(value === null || value === undefined || (typeof value === 'string' && value.trim().length === 0)
				|| (Array.isArray(value) && value.length === 0)){
            return
        }

        var customWidget = this.profile.customWidgetSettings[propertyType.code];
        var forceDisableRTF = this.profile.isForcedDisableRTF(propertyType);

        // Multi-value properties supply an array; normalize to a string before branching.
        // Spreadsheet branch uses `row` directly and doesn't call string methods on value.
        if (Array.isArray(value)) {
            if (customWidget === 'Word Processor') {
                value = value.filter(function(v) { return v != null && v !== ''; }).join('');
            } else if (customWidget !== 'Spreadsheet') {
                value = value.filter(function(v) { return v != null && v !== ''; }).join('\n\n');
            }
        }

        if(!forceDisableRTF) {
            var $value = null
            var renderTooltip = null

            if(customWidget === 'Word Processor'){
                // Start of Heuristic: Removes leading titles from DOCUMENT properties rendered in table cells
                if(
                (propertyType.code === 'DOCUMENT' || propertyType.code === '$DOCUMENT') &&
                value.startsWith('<h2>')
                ) {
                    var indexOfEndH2 = value.indexOf('</h2>');
                    value = value.substring(indexOfEndH2 + '</h2>'.length);
                }
                // End of Heuristic
                var valueLowerCase = value.toLowerCase();
                if(valueLowerCase.includes("<img") || valueLowerCase.includes("<table")){
                    $value = $("<img>", { src : "./img/file-richtext.svg", "width": "24px", "height": "24px"})
                    renderTooltip = function(){
                        var output = $("<div>");
                        var $btn = null;
                        $btn = $("<a>", { 'class' : 'btn btn-showhide' });
                        $btn.css("padding", "0px");
                        var iconType = IconUtil.getToolbarIconType("CLOSE");
                        var icon = IconUtil.getIcon(iconType);
                        $btn.append(icon);
                        $btn.attr('id', 'tooltip-close');

                        var valueSanitized = FormUtil.sanitizeRichHTMLText(value);
                        $tooltip = FormUtil.getFieldForPropertyType(propertyType, valueSanitized);
                        $tooltip = FormUtil.activateRichTextProperties($tooltip, undefined, propertyType, valueSanitized, true);
                        output.append($btn).append($tooltip);
                        return output;
                    }
                } else{
                    return $("<div>").html(FormUtil.sanitizeRichHTMLText(value))
                }
            }else if(customWidget === 'Spreadsheet'){
                $value = $("<img>", { src : "./img/table.svg", "width": "16px", "height": "16px"})
                renderTooltip = function(){
                    var output = $("<div>");
                    var $btn = null;
                    $btn = $("<a>", { 'class' : 'btn btn-showhide' });
                    $btn.css("padding", "0px");
                    var iconType = IconUtil.getToolbarIconType("CLOSE");
                    var icon = IconUtil.getIcon(iconType);
                    $btn.append(icon);
                    $btn.attr('id', 'tooltip-close');

                    $tooltip = $("<div>")
                    JExcelEditorManager.createField($tooltip, FormMode.VIEW, propertyType.code, { properties: row });

                    output.append($btn).append($tooltip);
                    return output;
                }
            }else{
                $value = $("<div>")
                value.split('\n').forEach(function(line){
                    $("<div>").text(line).appendTo($value)
                })
                return $value
            }

            $value.tooltipster({
                trigger: 'click',
                interactive: true,
                trackTooltip: true,
                trackerInterval: 100,
                theme: 'tooltipster-shadow',
                functionBefore: function(instance, helper){
                    var $content = $("<div>").css({ "max-width" : "50vw", "max-height" : "50vh"}).append(renderTooltip())
                    $(helper.origin).tooltipster('content', $content)
                    return true
                },
                functionReady: function(origin, tooltip) {
                    $("#" + tooltip.tooltip.id +' #tooltip-close').click(function(){
                        origin.hide();
                    });
                }
            })

            $valueContainer = $("<span>", { style: "cursor: pointer" })
            $valueContainer.append($value)
            return $valueContainer
        }else{
            $value = $("<div>")
            value.split('\n').forEach(function(line){
                $("<div>").text(line).appendTo($value)
            })
            return $value
        }
    }

