// Don't bind events when the UI is block or Select2 will not work correctly.
$.blockUI.defaults.bindEvents = false;

var Select2Manager = new function() {
	var toInitialize = [];
	var isPolling = false;
	
	this.add = function(element, properties) {
		toInitialize.push({
			element : element,
			properties : properties,
		});
		if (isPolling === false) {
			isPolling = true;
			setTimeout(_polling, 50);
		}
	}
	
	var _polling = function() {
		try {
			var toReschedule = [];
			while(toInitialize.length > 0) {
				var next = toInitialize.shift();
				if (_isInDom(next.element)) {
					if(next.properties) {
						next.properties.width = '100%';
						next.properties.theme = "bootstrap";
					} else {
						next.properties = { width: '100%', theme: "bootstrap" };
					}
					next.element.select2(next.properties ? next.properties : { width: '100%', theme: "bootstrap" });
				} else {
					toReschedule.push(next);
				}	
			}
			
			toInitialize = toReschedule;
			
			if (toInitialize.length === 0) {
				isPolling = false;
			} else {
				setTimeout(_polling, 50);
			}
			
		} catch(err) {
			isPolling = false;
			toInitialize = [];
		}
	}
	
	var _isInDom = function(element) {
		var el = element[0];
		while (el = el.parentNode) {
			if (el === document) {
				return true;
			}
		}
		return false;
	}
}
;
var CKEditorManager = new function() {

    var editors = new Map();

    this.getEditors = function() {
        return editors;
    }

    this.addEditor = function(id, editor) {
        this.SpecialCharactersGreekExtended(editor);
        this.releaseResources();
        editors.set(id, editor);
    }

    this.releaseResources = function() {
        for (let key of editors.keys()) {
            let editor = editors.get(key);
            if(!editor.sourceElement.isConnected) {
                editor.destroy().catch( error => {console.log( error );});
                editors.delete(key);
            }
        }
    }

    this.getEditorById = function(id) {
        return editors.get(id);
    }

    this.getMaximized = function() {
        var ckMaximized = false;
        for (let editor of editors.values()) {
            var commands = editor.commands;
            if(commands && commands.maximize && commands.maximize.state == 1) {
                ckMaximized = true;
            }
        }
        return ckMaximized;
    }

	this.destroy = function() {
	    for (let editor of editors.values()) {
	        editor.destroy().catch( error => {console.log( error );});
	    }
	    editors.clear();
	}

	this.SpecialCharactersGreekExtended = function(editor) {
	    editor.plugins.get( 'SpecialCharacters' ).addItems( 'Greek', [
            { title: 'Alpha lowercase'      , character: 'α' },
            { title: 'Beta lowercase'       , character: 'β' },
            { title: 'Gamma lowercase'      , character: 'γ' },
            { title: 'Delta lowercase'      , character: 'δ' },
            { title: 'Epsilon lowercase'    , character: 'ε' },
            { title: 'Zeta lowercase'       , character: 'ζ' },
            { title: 'Eta lowercase'        , character: 'η' },
            { title: 'Theta lowercase'      , character: 'θ' },
            { title: 'Iota lowercase'       , character: 'ι' },
            { title: 'Kappa lowercase'      , character: 'κ' },
            { title: 'Lambda lowercase'     , character: 'λ' },
            { title: 'Mu lowercase'         , character: 'μ' },
            { title: 'Nu lowercase'         , character: 'ν' },
            { title: 'Xi lowercase'         , character: 'ξ' },
            { title: 'Omicron lowercase'    , character: 'ο' },
            { title: 'Pi lowercase'         , character: 'π' },
            { title: 'Rho lowercase'        , character: 'ρ' },
            { title: 'Sigma lowercase'      , character: 'σ' },
            { title: 'Sigma lowercase (final position)' , character: 'ς' },
            { title: 'Tau lowercase'        , character: 'τ' },
            { title: 'Upsilon lowercase'    , character: 'υ' },
            { title: 'Phi lowercase'        , character: 'φ' },
            { title: 'Chi lowercase'        , character: 'χ' },
            { title: 'Psi lowercase'        , character: 'ψ' },
            { title: 'Omega lowercase'      , character: 'ω' },

            { title: 'Alpha uppercase'      , character: 'Α' },
            { title: 'Beta uppercase'       , character: 'Β' },
            { title: 'Gamma uppercase'      , character: 'Γ' },
            { title: 'Delta uppercase'      , character: 'Δ' },
            { title: 'Epsilon uppercase'    , character: 'Ε' },
            { title: 'Zeta uppercase'       , character: 'Ζ' },
            { title: 'Eta uppercase'        , character: 'Η' },
            { title: 'Theta uppercase'      , character: 'Θ' },
            { title: 'Iota uppercase'       , character: 'Ι' },
            { title: 'Kappa uppercase'      , character: 'Κ' },
            { title: 'Lambda uppercase'     , character: 'Λ' },
            { title: 'Mu uppercase'         , character: 'Μ' },
            { title: 'Nu uppercase'         , character: 'Ν' },
            { title: 'Xi uppercase'         , character: 'Ξ' },
            { title: 'Omicron uppercase'    , character: 'Ο' },
            { title: 'Pi uppercase'         , character: 'Π' },
            { title: 'Rho uppercase'        , character: 'Ρ' },
            { title: 'Sigma uppercase'      , character: 'Σ' },
            { title: 'Tau uppercase'        , character: 'Τ' },
            { title: 'Upsilon uppercase'    , character: 'Υ' },
            { title: 'Phi uppercase'        , character: 'Φ' },
            { title: 'Chi uppercase'        , character: 'Χ' },
            { title: 'Psi uppercase'        , character: 'Ψ' },
            { title: 'Omega uppercase'      , character: 'Ω' }
        ]);
	}

    this.imagePattern = "<img src=";
    this.servicePattern = "/openbis/openbis/file-service/eln-lims/";
	this.isDataValid = function(data) {
	    var domain = window.location.hostname;
	    var offset = 0;
	    while(offset < data.length) {
	        var indexOf = data.indexOf(this.imagePattern, offset);
	        if(indexOf > 0) {
	            // 1. Move offset
	            offset = indexOf + this.imagePattern.length + 1;
	            // 2. Check that image src
	            var dataCheckEnd = offset + this.servicePattern.length;
	            var dataCheck = data.substring(offset, dataCheckEnd);
	            // Uploaded imagine using the wizard
	            var startsWithServicePattern = this.servicePattern === dataCheck;
	            // Uploaded automatically
	            var isEmptySrc = '"' === dataCheck.charAt(0);
	            if(!startsWithServicePattern && !isEmptySrc) {
                    return false;
	            }
	        } else {
	            return true;
	        }
	    }
	    return true;
	}
}
;

var JExcelEditorManager = new function() {
    this.jExcelEditors = {}

    this.getOnChange = function(guid, propertyCode, entity) {
        var _this = this;
        return function(el, record, x, y, value) {
            var jExcelEditor = _this.jExcelEditors[guid];
            if(jExcelEditor) {
//                if(value) {
//                    // Change column width
//                    var columnWidth = parseInt(jExcelEditor.getWidth(x));
//                    var td = el.children[1].children[0].children[2].children[y].children[parseInt(x)+1];
//                    var columnScrollWidth = td.scrollWidth;
//
//                    if(columnScrollWidth > columnWidth) {
//                        jExcelEditor.setWidth(x, columnScrollWidth + 10);
//                    }
//                }
                // Save Editor
                var headers = jExcelEditor.getHeaders(true);
                var data = jExcelEditor.getData();
                var values = jExcelEditor.getData();
                // little hack because jExcelEditor.getData(false, true) is not returning processed results
                for(let rowIndex in values) {
                    values[rowIndex] = Object.values(values[rowIndex]).map((val, index) => {
                        if(_this._isString(val) && val.startsWith('=')) {
                            var row = parseInt(rowIndex)+1;
                            return jExcelEditor.getValue(headers[index] + row, true);
                        }
                        return val;
                    });
                }
                var style = jExcelEditor.getStyle();
                var meta = jExcelEditor.getMeta();
                var width = jExcelEditor.getWidth();
                var jExcelEditorValue = {
                    headers : headers,
                    data : data,
                    style : style,
                    meta : meta,
                    width : width,
                    values : values
                }
                var text = window.unescape(window.encodeURIComponent(JSON.stringify(jExcelEditorValue)));
                // force utf-8 encoding using TextEncoder
                var arr = new TextEncoder().encode(text);
                text = new TextDecoder("utf8").decode(arr);

                 entity.properties[propertyCode] = "<DATA>" + window.btoa(text) + "</DATA>";
            }
        }
    }

    this.getObjectFunction = function(guid) {
        var _this = this;
        return function() {
            var jExcelEditor = _this.jExcelEditors[guid];
            var x = null;
            var y = null;
            if(jExcelEditor.selectedCell) {
                x = parseInt(jExcelEditor.selectedCell[0]);
                y = parseInt(jExcelEditor.selectedCell[1]);
            } else {
                Util.showInfo("Select a cell first.");
                return;
            }

            var component = "<div>"
                component += "<legend>Insert Object</legend>";
            	component += "<div>";

                component += "<div class='form-group'>";
                component += "<label class='control-label'>Object:</label>";
                component += "<div>";
                component += "<div id='objectSelector'></div>";
                component += "</div>";
                component += "</div>";

                component += "<div class='form-group'>";
                component += "<label class='control-label'>Options:</label>";
                component += "<div class='controls'>";
                component += "<span class='checkbox'><label><input type='checkbox' id='insertHeaders'> Insert Headers </label></span>";
                component += "</div>";
                component += "</div>";

                component += "</div>";
                component += "</div>";
                Util.blockUI(component + "<a class='btn btn-default' id='insertAccept'>Accept</a> <a class='btn btn-default' id='insertCancel'>Cancel</a>", FormUtil.getDialogCss());

                var advancedEntitySearchDropdown = new AdvancedEntitySearchDropdown(true, true, "Select Object", false, true, false, false, false);
                advancedEntitySearchDropdown.init($("#objectSelector"));

                $("#insertCancel").on("click", function(event) {
                    Util.unblockUI();
                });

                $("#insertAccept").on("click", function(event) {
                    var insertHeaders = $("#insertHeaders")[0].checked;
                    var selected = advancedEntitySearchDropdown.getSelected();
                    var lastEntityKindType = null;

                    if(selected.length > 0) {
                        for(var sIdx = 0; sIdx < selected.length; sIdx++) {
                            var entity = selected[sIdx];
                            var entityKindType = entity["@type"] + ":" + entity.type.code;
                            var entityTable = _this.getEntityAsTable(entity);
                            var columnCount = jExcelEditor.getHeaders().split(',').length;
                            var rowCount = jExcelEditor.getData().length;
                            if(insertHeaders && lastEntityKindType !== entityKindType) {
                                //Insert Labels
                                for(var lIdx = 0; lIdx < entityTable.label.length; lIdx++) {
                                    var label = entityTable.label[lIdx];
                                    if(label) {
                                        for(;columnCount <= x+lIdx; columnCount++) {
                                            jExcelEditor.insertColumn();
                                        }
                                        for(;rowCount <= y;rowCount++) {
                                            jExcelEditor.insertRow();
                                        }
                                        jExcelEditor.setValueFromCoords(x+lIdx, y, label, true);
                                    }
                                }
                                y++;
                            }

                            //Insert Values
                            for(var vIdx = 0; vIdx < entityTable.value.length; vIdx++) {
                                var value = entityTable.value[vIdx];
                                if(value) {
                                    for(;columnCount <= x+vIdx; columnCount++) {
                                        jExcelEditor.insertColumn();
                                    }
                                    for(;rowCount <= y;rowCount++) {
                                        jExcelEditor.insertRow();
                                    }
                                    if(Array.isArray(value)) {
                                        // value = JSON.stringify(value);
                                        value = value.map(x => Array.isArray(x) ? "["+x.toString()+"]" : x).toString()
                                    }
                                    jExcelEditor.setValueFromCoords(x+vIdx, y, value, true);
                                }
                            }
                            y++;
                            lastEntityKindType = entityKindType;
                        }
                        Util.unblockUI();
                    } else {
                        Util.showInfo("Select an object first.", function() {}, true);
                    }
                });
        }
    }

	this.createField = function($container, mode, propertyCode, entity) {
        var _this = this;
        var rawValue = entity && entity.properties && entity.properties[propertyCode];

        // Multi-value spreadsheet: value is an array of encoded strings.
        // Render each slot in its own sub-container. For edit mode, proxy the getter/setter
        // so that onChange writes back to the correct index in the original array.
        if (Array.isArray(rawValue)) {
            rawValue.forEach(function(singleValue, idx) {
                var $subContainer = $('<div>').css('margin-bottom', '8px');
                $container.append($subContainer);
                var syntheticEntity = $.extend({}, entity);
                syntheticEntity.properties = $.extend({}, entity.properties);
                Object.defineProperty(syntheticEntity.properties, propertyCode, {
                    get: function() { return entity.properties[propertyCode][idx]; },
                    set: function(v) { entity.properties[propertyCode][idx] = v; },
                    configurable: true,
                    enumerable: true
                });
                _this.createField($subContainer, mode, propertyCode, syntheticEntity);
            });
            $container.refresh = function() {};
            return;
        }

	    $container.attr('style', 'width: 100%; height: 450px; overflow-y: scroll; overflow-x: scroll;');

        var headers = null;
	    var data = [];
	    var style = null;
	    var meta = null;
        var width = null;
	    if(entity && entity.properties && entity.properties[propertyCode]) {
	        var jExcelEditorValueAsStringWithTags = entity.properties[propertyCode];
	        var jExcelEditorValue = null;
	        if(jExcelEditorValueAsStringWithTags) {
	            var jExcelEditorValueAsStringNoTags = jExcelEditorValueAsStringWithTags.substring(6, jExcelEditorValueAsStringWithTags.length - 7);
                try {
                    // Improved decoding, used for the new encoding
                    jExcelEditorValue = JSON.parse(window.decodeURIComponent(window.escape(window.atob(jExcelEditorValueAsStringNoTags))));
                } catch (error) {
                    // Original decoding, used to support systems until they update
                    jExcelEditorValue = JSON.parse(window.atob(jExcelEditorValueAsStringNoTags));
                }
	        }
	        if(jExcelEditorValue) {
	            headers = jExcelEditorValue.headers;
	            data = jExcelEditorValue.data;
	            style = jExcelEditorValue.style;
	            meta = jExcelEditorValue.meta;
	            width = jExcelEditorValue.width;
	        }
	    }

        var guid = Util.guid();

        // jspreadsheet v5: worksheet options are nested under worksheets[]
        var worksheetOptions = {
            data: data,
            style: style,
            meta: meta,
            editable: mode !== FormMode.VIEW,
            minDimensions: [10, 10],
        };

        if(headers) {
            worksheetOptions.columns = headers.map(function(h, i) {
                return { title: h, width: width ? width[i] : undefined };
            });
        }

        var options = {
            worksheets: [worksheetOptions],
            toolbar: null,
        };

        if(mode === FormMode.VIEW) {
            worksheetOptions.allowInsertRow = false;
            worksheetOptions.allowManualInsertRow = false;
            worksheetOptions.allowInsertColumn = false;
            worksheetOptions.allowManualInsertColumn = false;
            worksheetOptions.allowDeleteRow = false;
            worksheetOptions.allowDeleteColumn = false;
            worksheetOptions.allowRenameColumn = false;
            worksheetOptions.allowComments = false;
            worksheetOptions.contextMenu = function(obj, x, y, e) {
                return [];
            };
            options.onload = function() {
                var spreadsheet = _this.jExcelEditors[guid];
                if (!spreadsheet) {
                    return;
                }
                var data = spreadsheet.getData();
                var headers = spreadsheet.getHeaders().split(',');
                var cellsWithIdentifiers = [];
                var cellsWithPermIds = [];
                var identifiers = new Set();
                var permIds = new Set();
                for (let i=0; i<data.length; i++ ) {
                    for(let j=0; j < data[i].length; j++) {
                        let cellData = data[i][j];
                        let permIdsInCell = _this.getPermIdsFromCell(cellData);
                        if(permIdsInCell && permIdsInCell.length > 0) {
                            let cellIndex = headers[j] + (i+1);
                            let cell = spreadsheet.getCell(cellIndex);
                            permIdsInCell.forEach(x => permIds.add(x));
                            cellsWithPermIds.push({cell: cell, cellData: cellData});
                            cell.innerHTML = Util.getProgressBarSVG();
                        }
                        if(_this._isIdentifierCell(cellData)) {
                            let cellIndex = headers[j] + (i+1);
                            let cell = spreadsheet.getCell(cellIndex);
                            cellsWithIdentifiers.push({cell: cell, cellData: cellData});
                            cellData.split(/\s+/)
                                .filter(_this._isIdentifier)
                                .forEach(id => identifiers.add(id));
                            cell.innerHTML = Util.getProgressBarSVG();
                        }
                    }
                }
                _this._searchByIdentifiers(Array.from(identifiers), function(results) {

                    for(cell of cellsWithIdentifiers) {
                        var stringArray = cell.cellData.split(/(\s+)/);
                        var cellText = "";
                        for (let word of stringArray) {
                            if(results[word]) {
                                cellText += results[word][0].outerHTML;
                            } else {
                                cellText += word;
                            }
                        }
                        cell.cell.innerHTML = cellText;

                        cell.cell.onclick = function(event) {
                            results[event.target.innerText].click();
                        }
                    }

                });
                _this._searchByPermIds(Array.from(permIds), function(results) {
                    for(cell of cellsWithPermIds) {
                        var stringArray = cell.cellData.split(/(\s+|,\s*)/);
                        var cellText = "";
                        for (let word of stringArray) {
                            if(results[word]) {
                                cellText += results[word][0].outerHTML;
                            } else {
                                cellText += word;
                            }
                        }
                        cell.cell.innerHTML = cellText;

                        cell.cell.onclick = function(event) {
                            results[event.target.innerText].click();
                        }
                    }
                });
            }
        } else {
            var onChangeHandler = this.getOnChange(guid, propertyCode, entity);
            options.onundo = onChangeHandler;
            options.onredo = onChangeHandler;
            options.onchange = onChangeHandler;
            options.onafterchanges = onChangeHandler;
            options.oninsertrow = onChangeHandler;
            options.oninsertcolumn = onChangeHandler;
            options.ondeleterow = onChangeHandler;
            options.ondeletecolumn = onChangeHandler;
            options.onmoverow = onChangeHandler;
            options.onmovecolumn = onChangeHandler;
            options.onresizerow = onChangeHandler;
            options.onresizecolumn = onChangeHandler;
            options.onsort = onChangeHandler;
            options.onpaste = onChangeHandler;
            options.onmerge = onChangeHandler;
            options.onchangeheader = onChangeHandler;
            options.oneditionend = onChangeHandler;
            options.onchangestyle = onChangeHandler;
            options.onchangemeta = onChangeHandler;

            options.toolbar = function(toolbar) {
                var remove = new Set(['undo', 'redo', 'save', 'web', 'fullscreen']);
                var itemsCount = toolbar.items.length;
                toolbar.items = toolbar.items.filter(function(item, index) {
                    return !(
                        (item.type === 'divisor' && index < itemsCount - 1) ||
                        remove.has(item.content) ||
                        (item.options && item.options.length > 0 &&
                            (item.options[0].startsWith('border_') || item.options[0].startsWith('vertical_')))
                    );
                });
                toolbar.items.push({ content: 'input', onclick: _this.getObjectFunction(guid) });
                return toolbar;
            };
        }

        var instances = jspreadsheet($container[0], options);
        _this.jExcelEditors[guid] = instances[0];

        $container.refresh = function() {};
	}

	this._isIdentifierCell = function(cellData) {
	    if(!this._isString(cellData) || cellData === '') {
	        return false;
	    }
	    var arr = cellData.split(/\s+/).filter(Boolean);
        for(let element of arr) {
            if(this._isIdentifier(element)) {
                return true;
            }
        }
        return false;
	}

    this.getPermIdsFromCell = function(cellData) {
        if(!this._isString(cellData) || cellData === '') {
            return [];
        }
        var arr = cellData.split(/\s+|,\s*/).filter(Boolean);
        var permIdRegexp = /\d{17}-\d+/g
        var ids = []
        for(let element of arr) {
            var permIds = element.match(permIdRegexp);
            if ( !permIds) {
                permIds = [];
            }
            ids = ids.concat(permIds);
        }
        return ids;
    }

	this._isString = function(value) {
        return typeof value === 'string' || value instanceof String;
	}

	this._isIdentifier = function(data) {
        var split = data.split('/');
        return split[0] == '' && (split.length > 2 && split.length < 6);
	}

	this._searchByIdentifiers = function(identifiers, callback) {

	    require([ "as/dto/sample/id/SampleIdentifier", "as/dto/sample/fetchoptions/SampleFetchOptions",
	     "as/dto/experiment/id/ExperimentIdentifier", "as/dto/experiment/fetchoptions/ExperimentFetchOptions"],
                    function(SampleIdentifier, SampleFetchOptions, ExperimentIdentifier, ExperimentFetchOptions) {

                        var sampleFetchOptions = new SampleFetchOptions();

                        var ids = identifiers.map(id => new SampleIdentifier(id));

                        mainController.openbisV3.getSamples(ids, sampleFetchOptions).done(function(sampleResults) {
                            let links = {};
                            let missing = []
                            for(let id of identifiers) {
                                if(sampleResults[id]) {
                                    let sample = sampleResults[id];
                                    links[id] = FormUtil.getFormLink(sample.identifier.identifier, 'Sample', sample.permId.permId, null);
                                } else {
                                    missing.push(id);
                                }
                            }
                            if(missing.length === 0) {
                                callback(links);
                            } else {
                                var experimentFetchOptions = new ExperimentFetchOptions();
                                var ids = missing.map(id => new ExperimentIdentifier(id));
                                mainController.openbisV3.getExperiments(ids, experimentFetchOptions).done(function(experimentResults) {
                                    var experiments = Util.mapValuesToList(experimentResults);
                                    for ( let experiment of experiments) {
                                        links[experiment.identifier.identifier] = FormUtil.getFormLink(experiment.identifier.identifier, 'Experiment', experiment.identifier.identifier, null);
                                    }
                                    callback(links);
                                }).fail(function(result) {
                                    callback(links);
                                });
                            }
                        }).fail(function(result) {
                            callback({});
                        });
                    });

	}

    this._searchByPermIds = function(permIds, callback) {

        require([ "as/dto/sample/id/SamplePermId", "as/dto/sample/fetchoptions/SampleFetchOptions",
                "as/dto/experiment/id/ExperimentPermId", "as/dto/experiment/fetchoptions/ExperimentFetchOptions",
                "as/dto/dataset/id/DataSetPermId", "as/dto/dataset/fetchoptions/DataSetFetchOptions"],
            function(SamplePermId, SampleFetchOptions, ExperimentPermId, ExperimentFetchOptions, DataSetPermId, DataSetFetchOptions) {

                var sampleFetchOptions = new SampleFetchOptions();

                var ids = permIds.map(id => new SamplePermId(id));

                mainController.openbisV3.getSamples(ids, sampleFetchOptions).done(function(sampleResults) {
                    let links = {};
                    let missing = []
                    for(let id of permIds) {
                        if(sampleResults[id]) {
                            let sample = sampleResults[id];
                            links[id] = FormUtil.getFormLink(sample.identifier.identifier, 'Sample', sample.permId.permId, null);
                            links[sample.identifier.identifier] = FormUtil.getFormLink(sample.identifier.identifier, 'Sample', sample.permId.permId, null);
                        } else {
                            missing.push(id);
                        }
                    }
                    if(missing.length === 0) {
                        callback(links);
                    } else {
                        var experimentFetchOptions = new ExperimentFetchOptions();
                        var ids = missing.map(id => new ExperimentPermId(id));
                        mainController.openbisV3.getExperiments(ids, experimentFetchOptions).done(function(experimentResults) {
                            let missingV2 = []
                            for(let id of missing) {
                                if(experimentResults[id]) {
                                    let experiment = experimentResults[id];
                                    links[id] = FormUtil.getFormLink(experiment.identifier.identifier, 'Experiment', experiment.permId.permId, null);
                                    links[experiment.identifier.identifier] = FormUtil.getFormLink(experiment.identifier.identifier, 'Experiment', experiment.permId.permId, null);
                                } else {
                                    missingV2.push(id);
                                }
                            }
                            if(missing.length === 0) {
                                callback(links);
                            } else {
                                var dataSetFetchOptions = new DataSetFetchOptions();
                                var ids = missing.map(id => new DataSetPermId(id));
                                mainController.openbisV3.getDataSets(ids, dataSetFetchOptions).done(function(dataSetResults) {
                                    var dataSets = Util.mapValuesToList(dataSetResults);
                                    for ( let dataSet of dataSets) {
                                        links[dataSet.permId.permId] = FormUtil.getFormLink(dataSet.permId.permId, 'DataSet', dataSet.permId.permId, null);
                                    }
                                    callback(links);
                                }).fail(function(result) {
                                    callback(links);
                                });
                            }

                        }).fail(function(result) {
                            callback(links);
                        });
                    }
                }).fail(function(result) {
                    callback({});
                });
            });

    }

	this.getEntityAsTable = function(entity) {
	    var tableModel = {
	        code : [],
	        label : [],
	        value : [],
	        dataType : [],
	    }

	    if(entity["@type"] === "as.dto.sample.Sample") {
            var sampleType = profile.getSampleTypeForSampleTypeCode(entity.type.code);

            tableModel.code.push("");
            tableModel.label.push("Identifier");
            tableModel.value.push(entity.identifier.identifier);
            tableModel.dataType.push("");

            for(var i = 0; i < sampleType.propertyTypeGroups.length; i++) {
                var propertyGroup = sampleType.propertyTypeGroups[i].propertyTypes;
                for(var j = 0; j < propertyGroup.length; j++) {
            	    var propertyType = propertyGroup[j];
            	    tableModel.code.push(propertyType.code);
            	    tableModel.label.push(propertyType.label);
            	    tableModel.value.push(entity.properties[propertyType.code]);
            	    tableModel.dataType.push(propertyType.dataType);
                }
            }
	    }
	    return tableModel;
	}
}
