function SampleField(isRequired,
					 placeholder,
					 sampleTypeCode,
					 initialValue,
					 isDisabled,
					 isMultiValue) {
    var _this = this;
	var isRequired = isRequired;
	var placeholder = placeholder;
	var sampleTypeCode = sampleTypeCode;
	var selectId = "sample-field-id-" + Util.guid();
	var $plainSelect = FormUtil.getPlainDropdown({}, "", selectId);
	var selectOptions = null;

    var initialised = false;
	var storedParams = null;
	var changeListener = null;
    var isSingleValue = true;
    if (isMultiValue) {
        isSingleValue = false;
    }
    this.getInitialValue = function(value) {
        if(value) {
            if(Array.isArray(value)) {
                return value;
            } else {
                return initialValue.split(',').map(x => x.trim());
            }
        } else {
            return value;
        }
    }
    var initialValue = this.getInitialValue(initialValue);


	//
	// Form API
	//

	this.setValue = function(v3Sample) {
		var data = {
				id : v3Sample.permId.permId,
				text : Util.getDisplayNameForEntity2(v3Sample),
				data : v3Sample
		};
		var newOption = new Option(data.text, data.id, true, true);
		newOption.data = data;
		newOption.title = data.text;
		$plainSelect.append(newOption).trigger('change');
	}


	this.val = function(samplePermId) {
	    if(!initialised) {
	        if(samplePermId) {
                if(Array.isArray(samplePermId)) {
                    initialValue = samplePermId;
                } else {
                    initialValue = [samplePermId];
                }
            }
	        return;
	    } else if(samplePermId === undefined) {
	        var selected = $plainSelect.select2('data');
	        if(selected && selected[0]) {
	            if(isSingleValue) {
                    return selected[0].id;
                } else {
                    return selected.map(x => x.id);
                }
	        } else {
	            return null;
	        }
	    } else {
            require([ "as/dto/sample/id/SamplePermId", "as/dto/sample/fetchoptions/SampleFetchOptions" ],
            function(SamplePermId, SampleFetchOptions) {
				for (let singlePermId of samplePermId) {
					var id1 = new SamplePermId(singlePermId);
	        	    var fetchOptions = new SampleFetchOptions();
	        	    fetchOptions.withProperties();
	        	    mainController.openbisV3.getSamples([ id1 ], fetchOptions).done(function(map) {
	        	        _this.setValue(Object.values(map)[0]);
	        	    });
				}
            });
	    }
	}

    $plainSelect.change = function(listener) {
        changeListener = listener;
    }

    $plainSelect.val = this.val;

    this.attr = function(attrName) {
        return $plainSelect.attr(attrName);
    }

	
	//
	// Search Entity
	//

	var searchSample = function(action) {
        var criteria = null;

        if(sampleTypeCode) {
            criteria = {
                entityKind : "SAMPLE",
                logicalOperator : "OR",
                rules : {},
                subCriteria : {
                    "1": {
                        entityKind : "SAMPLE",
                        logicalOperator : "AND",
                        rules : {
                            "1-1": { type : "Attribute", name : "SAMPLE_TYPE", value : sampleTypeCode },
                            "1-2": { type: "Property/Attribute", 	name: "ATTR.CODE", operator : "thatContains", 		value: storedParams.data.q }
                        }
                    },
                    "2": {
                        entityKind : "SAMPLE",
                        logicalOperator : "AND",
                        rules : {
                            "2-1": { type : "Attribute", name : "SAMPLE_TYPE", value : sampleTypeCode },
                            "2-2": { type: "Property/Attribute", 	name: "PROP." + profile.getInternalNamespacePrefix() + "NAME", operator : "thatContainsString", value: storedParams.data.q }
                        }
                    }
                }
            }
        } else {
            criteria = {
                entityKind : "SAMPLE",
                logicalOperator : "OR",
                rules : {
                    "1": { type: "Property/Attribute", 	name: "PROP." + profile.getInternalNamespacePrefix() + "NAME", operator : "thatContainsString", value: storedParams.data.q },
                    "2": { type: "Property/Attribute", 	name: "ATTR.CODE", operator : "thatContains", value: storedParams.data.q }
                }
            };
        }

		mainController.serverFacade.searchForSamplesAdvanced(criteria, {
			only : true,
			withType : true,
			withProperties : true,
			withExperiment : true,
			withExperimentProperties : true
		}, function(results) { results.type = "Samples"; action(results) });
	}

	//
	// Build Select
	//

    $plainSelect.attr("multiple", "multiple");
    if(isRequired) {
        $plainSelect.attr("required", "required");
    }
    if(isDisabled) {
        $plainSelect.attr("disabled", "disabled");
    }

    Util.onIsInPage($plainSelect[0], function() {

            selectOptions = {
                width: '100%',
                theme: "bootstrap",
                minimumInputLength: 2,
                allowClear: true,
                placeholder : placeholder,
                ajax: {
                    delay: 1000,
                    processResults: function (data) {
                        var results = [];

                        for(var dIdx = 0; dIdx < data.length; dIdx++) {
                            var group = {
                                text: data[dIdx].type,
                                children : []
                            }

                            var entities = data[dIdx].objects;
                            for(var eIdx = 0; eIdx < entities.length; eIdx++) {
                                group.children.push({
                                id : entities[eIdx].permId.permId,
                                text : Util.getDisplayNameForEntity2(entities[eIdx]),
                                data : {
                                    id : entities[eIdx].permId.permId,
                                    text : Util.getDisplayNameForEntity2(entities[eIdx]),
                                    data : entities[eIdx]
                                    }
                                })
                            }

                            if(entities.length > 0) {
                                results.push(group);
                            }
                        }

                        return {
                            "results": results,
                            "pagination": {
                                "more": false
                            }
                        };
                    },
                    transport: function (params, success, failure) {
                        storedParams = params;

                        // Searches
                        var searches = [searchSample];
                        var searchesResults = [];

                        var action = null;
                        action = function(result) {
                            searchesResults.push(result);
                            if(searches.length > 0) {
                                var search = searches.shift();
                                search(action);
                            } else {
                                success(searchesResults);
                            }
                        };

                        var search = searches.shift();
                        search(action);
                        return {
                            abort : function () { /*Not implemented*/ }
                        }
                    }
                }
            };

            if(isSingleValue) {
                selectOptions['maximumSelectionLength'] = 1;
            } else {
                selectOptions['closeOnSelect'] = false;
            }

            if(isDisabled) {
                selectOptions['escapeMarkup'] = function(markup) {
                    return markup;
                };

                selectOptions['templateSelection'] = function(data, container) {
                    var link = FormUtil.getFormLink(data.data, "Sample", data.id);
                    link.text(data.title ? data.title : data.text);
                    return link;
                };
            }

            $plainSelect.select2(selectOptions);

            $("body").on('select2:select', '#'+selectId, function (e) {
                if(changeListener) {
                    changeListener(null, _this.val());
                }
            });
            $("body").on('select2:unselect', '#'+selectId, function (e) {
                if(changeListener) {
                    changeListener(null, _this.val() ?? "");
                }
            });
            initialised = true;
            if(initialValue) {
                _this.val(initialValue);
            }
    });

    $plainSelect.refresh = function() {
        $plainSelect.select2(selectOptions);
    }

	return $plainSelect;
}

;
var EntityLinkWidget = new function()
{

    this.getEntityLinkDropdown = function(mode, sample, entityName) {
        if(mode !== FormMode.VIEW) {
            return null;
        }
        //
        return {
            // label - label in dropdown
            label: "Link entity to "+entityName,
            // title - tooltip
            title: "Link entity to "+entityName,
            action: function () {
                Util.blockUINoMessage();
                var component = $("<div>");
                component.append($("<legend>", { 'text' : "Link entity to "+entityName}))
                component.append($('<br>'));

                var $inputURL = $('<input>', {'type' : 'url', 'id' : 'input-logbook-url-' + mainController.getNextId(), 'alt' : entityName+' url', 'placeholder' : entityName+' url goes here', 'class' : 'form-control'});
                var value = '';
                if(sample && sample.metaData['ENTITY_LINK.URL']) {
                    value = sample.metaData['ENTITY_LINK.URL'];
                }
                $inputURL.val(value)
                var url = value;
                var keyupFunction = function(event){
                    var textField = $(this);
                    url = textField.val();
                };
                $inputURL.keyup(keyupFunction);

                var inputGroup = FormUtil.getFieldForComponentWithLabel($inputURL, 'URL');
                component.append(inputGroup);

                component.append($('<br>'));
                var acceptBtn = $("<a>", { 'class' : 'btn btn-primary', 'id' : 'updateAccept', 'text' : 'Accept' });
                var closeBtn = $("<a>", { 'class' : 'btn btn-default', 'id' : 'updateCancel', 'text' : 'Cancel' });
                component.append(acceptBtn).append('&nbsp;').append(closeBtn);

                Util.blockUI(component, FormUtil.getDialogCss());

                $("#updateAccept").on("click", function(event) {
                    require([
                            "as/dto/sample/update/SampleUpdate",
                            "as/dto/sample/id/SamplePermId"],
                        function (SampleUpdate, SamplePermId
                        ) {
                            const update = new SampleUpdate();
                            update.setSampleId(new SamplePermId(sample.permId.permId));
                            update.getMetaData().put('ENTITY_LINK.URL', url);

                            mainController.openbisV3.updateSamples([update]).done(function(x) {
                                let message = url ? "Entity linked" : "Entity unlinked";
                                mainController.refreshView();
                                Util.showSuccess(message, function () { Util.unblockUI(); });
                            }).fail(function(err) {
                                Util.showError(err.message, function() {}, true);
                            });

                        }
                    );
                });


                $("#updateCancel").on("click", function(event) {
                    Util.unblockUI();
                });

            }
        }
    }

    this.getEntityLinkContainer = function($container, model, customLinkCompiler) {
        if (model.mode === FormMode.VIEW &&
            model.v3_sample.metaData &&
            model.v3_sample.metaData['ENTITY_LINK.URL']) {

            var id = mainController.getNextId();
            var $div = $("<div>", {'id': 'iframe-container'});
            $div.css({
                'position': 'relative',
                'width': '100%'
            })
            var frameId = 'linked-frame-' + id;

            var $frame = $("<iframe>", { 'id': frameId});
            if(customLinkCompiler) {
                customLinkCompiler($frame, model.v3_sample.metaData['ENTITY_LINK.URL']);
            } else {
                $frame.attr('src', model.v3_sample.metaData['ENTITY_LINK.URL']);
            }

            $frame.css({
                'width': '100%',
                // 'height': '100%',
                'height': '500px',
                'display': 'block',
                'border': '1px solid #ccc'
            });

            var resizerId = 'resizer-' + id;
            var $resizer = $("<div>", {'id': resizerId});
            $resizer.css({
                'width': '100%',
                'height': '8px',
                'background': '#ddd',
                'cursor': 'ns-resize',
                'display': 'flex',
                'align-items': 'center',
                'justify-content': 'center'
            });

            $div.append($frame);

            $div.append($resizer);
            $container.append($div);


            let isResizing = false;
            let startY, startHeight;

            var dragFunction = function (e) {
                isResizing = true;
                startY = e.clientY;
                startHeight = $('#' + frameId).outerHeight();
                $('body').css('cursor', 'ns-resize');
                $('#' + frameId).css('pointer-events', 'none');
            };

            $resizer.mousedown(dragFunction);
            $resizer.refresh = function () {
                $resizer.off('mousedown');
                $resizer.mousedown(dragFunction);
            }

            $(document).on('mousemove', function (e) {
                if (!isResizing) return;
                const newHeight = Math.max(100, startHeight + (e.clientY - startY));
                $('#' + frameId).css('height', newHeight + 'px');
            });

            $(document).on('mouseup', function () {
                if (!isResizing) return;
                isResizing = false;
                $('body').css('cursor', '');
                $('#' + frameId).css('pointer-events', 'auto');
            });

            return $resizer;
        } else {
            return null;
        }
    }
}
