function UserManagementConfigController(mainController, mode) {
    this._mainController = mainController;
    this._userManagementConfigModel = new UserManagementConfigModel(mode);
    this._userManagementConfigView = new UserManagementConfigView(this, this._userManagementConfigModel);

    this.init = function(views) {
        this._userManagementConfigView.repaint(views);
    }

    this.save = function(config, callback) {
        try {
            JSON.parse(config);
        } catch (error) {
            Util.showError(error);
            return;
        }
        profile.userManagementMaintenanceTaskConfig = config;
        Util.blockUI();
        this._mainController.serverFacade.saveUserManagementMaintenanceTaskConfig(config, function() {
            Util.showSuccess("Successfully saved configuration of the User Management Maintenance Task.", function() {
                Util.unblockUI();
                callback();
            });
        });
    }

    this.saveAndExecute = function(config, callback) {
        var _this = this;
        var serverFacade = this._mainController.serverFacade;
        this.save(config, function() {
            Util.blockUI();
            serverFacade.executeUserManagementMaintenanceTask(function(executionId) {
                var executionView = new UserManagementExecutionView(callback);
                executionView.init();
                var _polling = function() {
                    serverFacade.getUserManagementMaintenanceTaskReport(executionId, function(report) {
                        var log = report[0];
                        var finishedMarker = "UserManagementMaintenanceTask - finished";
                        var index = log.indexOf(finishedMarker);
                        if (index > 0) {
                            executionView.updateLog(log.substring(0, index + finishedMarker.length));
                            executionView.finished(report[1], report[2]);
                            serverFacade.removeUserManagementMaintenanceTaskReport(executionId);
                        } else {
                            executionView.updateLog(log);
                            setTimeout(_polling, 1000);
                        }
                    });
                };
                _polling();
            });
        });
    }

    this.isDirty = function() {
        return this._userManagementConfigModel.isFormDirty;
    }
}
;
function UserManagementConfigModel(mode) {
    this.mode = mode;
    this.isFormDirty = false;
}
;
function UserManagementConfigView(userManagementConfigController, userManagementConfigModel) {
    this._userManagementConfigController = userManagementConfigController;
    this._userManagementConfigModel = userManagementConfigModel;

    this.repaint = function(views) {
        var _this = this;
        var $header = views.header;
        var $container = views.content;
        $container.empty();
        
        $header.append($("<h1>").append("User Management Config"));
        var $textarea = $('<textarea>', {'id' : 'userManagementConfigText', 
            'style' : 'height: 100%; width: 100%; resize: none', 'class' : 'form-control'});
        $textarea.val(profile.userManagementMaintenanceTaskConfig);
        $textarea.change(function(event) {
            _this._userManagementConfigModel.isFormDirty = true;
        });
        if (this._userManagementConfigModel.mode !== FormMode.EDIT) {
            $textarea.attr('readonly','readonly');
        }

        //
        // Toolbar
        //
        var toolbarModel = [];
        if (this._userManagementConfigModel.mode === FormMode.EDIT) {
            //Save
            var $saveBtn = FormUtil.getButtonWithIcon("glyphicon-floppy-disk", function() {
                _this._userManagementConfigController.save($textarea.val(), function() {
                    _this._userManagementConfigModel.isFormDirty = false;
                    mainController.changeView("showUserManagementConfigPage", FormMode.VIEW);
                });
            }, "Save", null, "save-btn");
            $saveBtn.removeClass("btn-default");
            $saveBtn.addClass("btn-primary");
            toolbarModel.push({ component : $saveBtn });
            //Save & Execute
            var $saveAndExecuteBtn = FormUtil.getButtonWithIcon("glyphicon-floppy-disk", function() {
                _this._userManagementConfigController.saveAndExecute($textarea.val(), function() {
                    _this._userManagementConfigModel.isFormDirty = false;
                    mainController.changeView("showUserManagementConfigPage", FormMode.VIEW);
                });
            }, "Save & Execute", null, "save-and-execute-btn");
            toolbarModel.push({ component : $saveAndExecuteBtn });
        } else {
            //Edit
            var $editButton = FormUtil.getButtonWithIcon("glyphicon-edit", function () {
                mainController.changeView("showUserManagementConfigPage", FormMode.EDIT);
            }, "Edit", null, "edit-btn", 'btn btn-primary btn-secondary');
            toolbarModel.push({ component : $editButton });
        }
        $header.append(FormUtil.getToolbar(toolbarModel));
        $container.append(FormUtil.getInfoBox("This is an expert feature which allows to change the configuration file "
                + "of the User Management Maintenance Task. For more details see " 
                + "<a href='" + profile.docuBaseUrl + "/User+Group+Management+for+Multi-groups+openBIS+Instances'>"
                + profile.docuBaseUrl + "/User+Group+Management+for+Multi-groups+openBIS+Instances</a>",
                []));
        $container.append($("<br>"));
        $container.append($textarea);
    }
}

function UserManagementExecutionView(callback) {
    this.$title;
    this.$textarea;
    this.$wait;
    this.$logButton;
    this.log;
    this.$auditButton;
    this.auditLog;
    this.$errorReportButton;
    this.errorReport;
    this.callback = callback;

    this.init = function() {
        var _this = this;
        var $dialog = $("<div>")
        $dialog.append($('<legend>').append('User Management Task Execution'));
        this.$title = $("<div>").text('Excerpt from the AS log file:')
        $dialog.append(this.$title);
        this.$textarea = $("<textarea>", {'id' : 'userManagementMaintenanceTaskLog', 'rows' : 16,
            'readonly' : 'readonly', 'style' : 'white-space: pre; font-size: small; width: 100%; resize: none'});
        $dialog.append(this.$textarea);

        $buttons = $("<div>", {'style' : 'margin-top: 10px'});
        $dialog.append($buttons);
        this.$wait = $("<span>", {'style' : 'color: red; text-align: center'});
        this.$wait.append("Please, wait until task has been finished.");
        $buttons.append(this.$wait);
        this.$logButton = FormUtil.getButtonWithText("Show AS Log", function() {
            _this.$title.text("AS log:");
            _this.$textarea.val(_this.log);
        });
        this.$logButton.hide();
        $buttons.append(this.$logButton);
        this.$auditButton = FormUtil.getButtonWithText("Show Audit Log", function() {
            _this.$title.text("Audit log:");
            _this.$textarea.val(_this.auditLog);
        });
        this.$auditButton.hide();
        $buttons.append('&nbsp;').append(this.$auditButton);
        this.$errorReportButton = FormUtil.getButtonWithText("Show Error Report", function() {
            _this.$title.text("Error report:");
            _this.$textarea.val(_this.errorReport);
        });
        this.$errorReportButton.hide();
        $buttons.append('&nbsp;').append(this.$errorReportButton);
        $closeButton = FormUtil.getButtonWithText("Close", function() {
            Util.unblockUI();
            _this.callback();
        });
        $closeButton.css("float", "right");
        $buttons.append($closeButton);

        Util.blockUI($dialog, {'text-align': 'left', 'left': '10%', 'top': '10%', 'width': '80%'});
    }

    this.updateLog = function(newLog) {
        this.log = newLog;
        this.$textarea.val(newLog);
    }
    
    this.finished = function(auditLog, errorReport) {
        this.$wait.hide();
        this.auditLog = auditLog;
        this.$logButton.show();
        this.$auditButton.show();
        if (errorReport !== "") {
            this.errorReport = errorReport;
            this.$errorReportButton.show();
            alert("Execution finished with an error.");
        }
    }
}

;
function CustomImportController(parentController) {
    this._parentController = parentController;
    this._model = new CustomImportModel();
    this._view = new CustomImportView(this, this._model);

    this.init = function(views) {
        this._view.repaint(views);
    }

    this.importFile = function(dropbox, callback) {
        Util.blockUI();
        var parameters = {
                "method": "dropDataSet",
                "dropBoxName": dropbox,
                "fileName": this._model.file
        };
        mainController.serverFacade.createReportFromAggregationService(profile.allDataStores[0].code, parameters, function(response) {
            if(response.error) { //Error Case 1
                Util.showError(response.error.message, Util.unblockUI);
            } else if (response.result.columns[1].title === "Error") { //Error Case 2
                var stacktrace = response.result.rows[0][1].value;
                Util.showStacktraceAsError(stacktrace);
            } else if (response.result.columns[0].title === "STATUS" && response.result.rows[0][0].value === "OK") { //Success Case
                callback();
            } else { //This should never happen
                Util.showError("Unknown Error.", Util.unblockUI);
            }
        });
    }

    this.getAttachment = function(entityKind, entityPermid, attachmentName, callback) {
        Util.blockUI();
        var handleAttachment = function(entity) {
            if (entity) {
                attachments = entity.getAttachments().filter(a => a.getFileName() === attachmentName);
                if (attachments.length > 0) {
                    Util.unblockUI();
                    callback(attachments[0]);
                } else {
                    Util.showError("There is no attachment file with name '" + attachmentName + " in " + entityKind 
                            + " with perm ID " + entityPermid + ".", Util.unblockUI);
                }
            } else {
                Util.showError("There is no " + entityKind + " with perm ID " + entityPermid + ".", Util.unblockUI);
            }
        };
        if (entityKind === "PROJECT") {
            mainController.serverFacade.getProjectWithAttachments(entityPermid, handleAttachment);
        } else if (entityKind === "EXPERIMENT") {
            mainController.serverFacade.getExperimentWithAttachments(entityPermid, handleAttachment);
        } else if (entityKind === "SAMPLE") {
            mainController.serverFacade.getSampleWithAttachments(entityPermid, handleAttachment);
        } else {
            Util.showError("Unknwon entity kind " +  entityKind 
                    + ". Allowed values are PROJECT, EXPERIMENT, and SAMPLE.", Util.unblockUI);
        } 
    }

}

