/**
 * Creates an instance of SideMenuWidget.
 *
 * @constructor
 * @this {SideMenuWidgetController}
 * @param {MainController} mainController Used to control view changes.
 */

function SideMenuWidgetController(mainController) {
    this._mainController = mainController
    this._sideMenuWidgetModel = new SideMenuWidgetModel()
    this._settingsMap = {
        "lab_notebook": {},
        "lims": {},
        "tools": {},
    }
    this._browserControllerMap = {
            "lab_notebook": new SideMenuWidgetBrowserController('lab_notebook', this._settingsMap),
            "lims": new SideMenuWidgetBrowserController('lims', this._settingsMap),
            "tools": new SideMenuWidgetBrowserController('tools', this._settingsMap)
    }

    this._sideMenuWidgetView = new SideMenuWidgetViewController(this, this._sideMenuWidgetModel);

    this._browserController = this._browserControllerMap['lab_notebook'];

    //
    // External API for real time updates
    //
    this.finalize = function() {
        this._sideMenuWidgetView.finalize();
    }

    this.getCurrentNodeId = function () {
        var nodeObject = this._browserController.getSelectedObject()

        if (nodeObject) {
            var nodeObjectStr = JSON.stringify(nodeObject)
            return nodeObjectStr
        } else {
            return null
        }
    }

    this.getCurrentTree = function() {
        return mainController.mainHeader.getCurrentPage();
    }

    this.changeCurrentTree = function(treeName, optionalNode) {
        this._browserController = this._browserControllerMap[treeName];
        this._sideMenuWidgetView.changeSideMenuView(treeName);
//        if(optionalNode) {
////            this.moveToNodeIdAfterLoad(optionalNode)
//        }
    }

    this.deleteNodeByEntityPermId = async function (entityType, entityPermId, isMoveToParent) {
        var _this = this

        var nodes = this._browserController.getNodes().filter(function (node) {
            if (node.object) {
                return entityType === node.object.type && entityPermId === node.object.id
            } else {
                return false
            }
        })

        for(var i = 0; i < nodes.length; i++){
            var node = nodes[i]
            await _this._browserController.reloadNode(node.parentId)
        }

        if (isMoveToParent) {
            var parentIds = nodes.map(function (node) {
                return node.parentId
            })

            while (parentIds.length > 0) {
                var parentId = parentIds.shift()
                if (!parentId) {
                    continue
                }

                var parent = _this._browserController.getNode(parentId)
                if (!parent) {
                    continue
                }

                if (parent.view && parent.viewData) {
                    mainController.changeView(parent.view, parent.viewData)
                    break
                } else {
                    parentIds.push(parent.parentId)
                }
            }

            if(parent){
                this.moveToNodeId(JSON.stringify(parent.object));
            }
        }
    }

    this.refreshCurrentNode = async function () {
        var _this = this
        var selectedObject = this._browserController.getSelectedObject()
        if (selectedObject) {
            var nodes = this._browserController.getNodes()
            for(var i = 0; i < nodes.length; i++){
                var node = nodes[i]
                if (selectedObject.type === node.object.type && selectedObject.id === node.object.id) {
                    await _this._browserController.reloadNode(node.id)
                }
            }
        }
    }

    this.refreshNodeByPermId = async function (entityType, entityPermId) {
        var _this = this
        var nodes = this._browserController.getNodes()
        for(var i = 0; i < nodes.length; i++){
            var node = nodes[i]
            if (node.object && entityType === node.object.type && entityPermId === node.object.id) {
                await _this._browserController.reloadNode(node.id)
            }
        }
    }

    this.refreshNodeParentByPermId = async function (entityType, entityPermId, callback) {
            var _this = this
            var nodes = this._browserController.getNodes()
            for(var i = 0; i < nodes.length; i++){
                var node = nodes[i]
                if (node.object && entityType === node.object.type && entityPermId === node.object.id) {
                    if(callback) {
                        await _this._browserController.reloadNode(node.parentId).then(() => callback())
                    } else {
                        await _this._browserController.reloadNode(node.parentId)
                    }
                    break;
                }
            }
        }

    this.moveToNodeId = function (nodeObjectStr) {
        var nodeObject = null

        try {
            nodeObject = JSON.parse(nodeObjectStr)
        } catch (e) {
            // do nothing
        }

        return this._browserController.selectObject(nodeObject, { ignore: true })
    }

    this.moveToNodeIdAfterLoad = function(nodeObj, shouldOpenPage, callback) {
        var _this = this;
        var _browserController = _this._browserController;
        var counter = 20;
        var repeatUntilSet = function() {
            if(counter <= 0) {
                return;
            }
           if(!_browserController.isLoading() && _browserController.isLoaded()) {
               let ignore = true;
               if(shouldOpenPage) {
                   ignore = false;
               }
               _browserController.selectObject(nodeObj, { ignore: ignore })
               if(callback) {
                   callback();
               }
           } else {
                counter--;
                setTimeout(repeatUntilSet, 500);
           }
        }
        repeatUntilSet();
    }

    this.getNodeSetAsRoot = function() {
        return this._browserController.getNodeSetAsRoot();
    }

    this.hasNodeWithObjectId = function(nodeId) {
        var _this = this
        var nodes = this._browserController.getNodes()
        for(var i = 0; i < nodes.length; i++){
            var node = nodes[i];
            if (node.object && nodeId.type === node.object.type && nodeId.id === node.object.id) {
                return true;
            }
        }
        return false;
    }

    this.setAsRootById = function (code) {
        var nodes = this._browserController.getNodes();
        var node = nodes.find(x => x.object.id === code);
        if(node) {
            this._browserController.setNodeAsRoot(node.id);
        }
    }

    //
    // Init method that builds the menu object hierarchy
    //
    this.init = function ($container, initCallback) {
        var _this = this

        this._mainController.serverFacade.getSetting(this._SORT_FIELD_KEY, function (sortField) {
            _this._sideMenuWidgetModel.sortField = sortField
            _this._sideMenuWidgetModel.$container = $container

            _this._sideMenuWidgetView.repaint($container)

            LayoutManager.addResizeEventHandler(_this.resizeSideMenuBody())

            initCallback()
        })
    }

    this.collapseSideMenu = function(reRender) {
        this.isCollapsed = true;
        LayoutManager._saveSettings();
        this._browserController._saveSettings()
        if(!LayoutManager.isMobile()) {
            this._sideMenuWidgetView.repaint(this._sideMenuWidgetModel.$container, true);
            if(reRender) {
                this._sideMenuWidgetView.repaintTreeMenu = true;
            }
            mainController.tabContent.refreshCurrentPage();
        } else {
            if(!LayoutManager.fullScreenFlag) {
                LayoutManager.fullScreen();
                this._sideMenuWidgetView.repaintCollapseButton(this._sideMenuWidgetModel.$container);
            }
        }

    }

    this.expandSideMenu = function() {
        this.isCollapsed = false;
        if(!LayoutManager.isMobile()) {
            this._sideMenuWidgetView.repaint(this._sideMenuWidgetModel.$container, false);
            mainController.tabContent.refreshCurrentPage();
        } else {
            if(LayoutManager.fullScreenFlag) {
                LayoutManager.restoreStandardSize();
                this._sideMenuWidgetView.repaintCollapseButton(this._sideMenuWidgetModel.$container);
            }
        }
        mainController.sideMenu.moveToNodeId(mainController.sideMenu.getCurrentNodeId());
        LayoutManager._saveSettings();
    }

    this.resizeElement = function ($elementBody, percentageOfUsage) {
        var currentTree = this.getCurrentTree();
        var $elementHead = $("#"+currentTree+"-sideMenuHeader")
        var sideMenuHeaderHeight = $elementHead.outerHeight()
        var $elementSortField = $("#"+currentTree+"-sideMenuSortBar")
        var sideMenuSortFieldHeight = $elementSortField.outerHeight()
        var $sideMenuFooter = $("#"+currentTree+"-sideMenuFooter")
        var sideMenuFooterHeight = $sideMenuFooter.outerHeight()
        var height = $(window).height()
        var availableHeight = height - sideMenuHeaderHeight - sideMenuSortFieldHeight  - LayoutManager.MAIN_HEADER_HEIGHT - sideMenuFooterHeight;
        $elementBody.css("height", availableHeight * percentageOfUsage)
    }

    this.resizeSideMenuBody = function () {
        var _this = this
        return function () {
            var currentTree = _this.getCurrentTree();
            var $elementBody = $("#"+currentTree+"-sideMenuBody")
            var percentageOfUsage = _this._sideMenuWidgetModel.percentageOfUsage
            _this.resizeElement($elementBody, percentageOfUsage)
        }
    }

    this.addSubSideMenu = function (subSideMenu, subSideMenuViewer) {
        var _this = this
        var sideMenuId = mainController.mainHeader.getCurrentPage();
        // Remove old from DOM if present
        if(this._sideMenuWidgetModel.subSideMenu[sideMenuId]) {
            this.removeSubSideMenu();
        }
        var elementId = subSideMenu.attr("id")
        $("#" + elementId).remove()
        // Add new
        this._sideMenuWidgetModel.subSideMenu[sideMenuId] = subSideMenu
        this._sideMenuWidgetView.currentView.subSideMenuViewer = subSideMenuViewer;
        if(!this.isCollapsed) {
            subSideMenu.css("margin-left", "3px")
            this._sideMenuWidgetModel.percentageOfUsage = 0.5
            $("[id='"+sideMenuId+"-sideMenuFooter']").remove()
            $("[id='"+sideMenuId+"-sideMenuTopContainer']").append(subSideMenu)
            if(!LayoutManager.isMobile()) {
                $("[id='"+sideMenuId+"-sideMenuTopContainer']").append(this._sideMenuWidgetView._expandedFooter())
            }
            this.resizeElement($("#"+sideMenuId+"-sideMenuBody"), 0.5)
            this.resizeElement(subSideMenu, 0.5)
        }
    }

    this.removeSubSideMenu = function () {
        var currentTree = this.getCurrentTree()
        if (this._sideMenuWidgetModel.subSideMenu[currentTree]) {
            this._sideMenuWidgetModel.subSideMenu[currentTree].remove()
            this._sideMenuWidgetModel.subSideMenu[currentTree] = null;
            this._sideMenuWidgetModel.percentageOfUsage = 1
            this.resizeElement($("#"+currentTree+"-sideMenuBody"), 1)
        }
        this._sideMenuWidgetModel.subSideMenu[currentTree] = null;
        this._sideMenuWidgetView.subSideMenuViewer = null;
    }
}

function SideMenuWidgetComponent(
    isSelectable,
    isTitle,
    displayName,
    uniqueId,
    parent,
    newMenuIfSelected,
    newViewIfSelected,
    newViewIfSelectedData,
    contextTitle
) {
    this.isSelectable = isSelectable
    this.isTitle = isTitle
    this.displayName = displayName
    this.uniqueId = uniqueId
    this.contextTitle = contextTitle
    this.parent = parent
    this.newMenuIfSelected = newMenuIfSelected
    this.newViewIfSelected = newViewIfSelected
    this.newViewIfSelectedData = newViewIfSelectedData
}

