    async _loadNodesSpaceSamples(params) {
        var sampleRules = {
                [Util.guid()]: { type: "Attribute", name: "SPACE", value: params.node.space },
                [Util.guid()]: { type: "Project", name: "NULL.NULL", value: "NULL" },
            }
        var sampleSubcriteria = []

        if (params.childrenIn) {
            sampleSubcriteria.push({
                logicalOperator: "OR",
                rules: params.childrenIn.map((childIn) => {
                    return {
                        type: "Attribute",
                        name: "PERM_ID",
                        value: childIn.object.id,
                    }
                }),
            })
        }

        if (params.childrenNotIn) {
            sampleSubcriteria.push({
                negate: true,
                logicalOperator: "OR",
                rules: params.childrenNotIn.map((childNotIn) => {
                    return {
                        type: "Attribute",
                        name: "PERM_ID",
                        value: childNotIn.object.id,
                    }
                }),
            })
        }

        var sampleFetchOptions = {
            only: true,
            withProperties: true,
            withType: true,
            withExperiment: true,
            withParents: true,
            withParentsExperiment: true,
            withParentsSpace: true,
            withDataSets: true,
            withDataSetSample: true,
            withSpace: true,
            from: params.offset,
            count: params.limit,
            sortings: [],
        }

        if (params.node.sortings) {
            var sampleSorting = params.node.sortings.find((sorting) => sorting.id === params.node.sortingId)
            if (sampleSorting) {
                sampleFetchOptions.sortings = sampleSorting.server
            }
        }

        return new Promise((resolve) => {
            mainController.serverFacade.searchForSamplesAdvanced(
                {
                    entityKind: "SAMPLE",
                    logicalOperator: "AND",
                    rules: sampleRules,
                    subCriteria: sampleSubcriteria,
                },
                sampleFetchOptions,
                (searchResult) => {
                    if(searchResult.totalCount > 0 && profile.isAFSAvailable()) {
                        var promises = [];
                        var parentless = [];
                        searchResult.objects.forEach((sample) => {
                            if(this._isSampleTypeOnNav(sample) && sample.parents && !sample.parents.some(parent => parent.space && parent.space.permId.permId === sample.space.permId.permId)  ) {
                               promises.push(mainController.openbisV3.getAfsServerFacade().list(sample.permId.permId ,"", false))
                               parentless.push(sample);
                            }
                        })

                        resolve(
                            Promise.all(promises.map(p => p.catch(e => e))).then(afsResult => {
                                var files = afsResult.filter(output => !(output instanceof Error));
                                var results = { nodes: [], totalCount: searchResult.totalCount }

                                parentless.forEach((sample) => {
                                    var hasAfsFile = files.some(file => file.length > 0 && file[0].owner === sample.permId.permId);
                                    results.nodes.push(this._createSampleNode(sample, hasAfsFile));
                                })
                                return results;
                            })
                        )
                    } else {
                        var results = { nodes: [], totalCount: searchResult.totalCount }

                        searchResult.objects.forEach((sample) => {
                            if(this._isSampleTypeOnNav(sample) && sample.parents && !sample.parents.some(parent => parent.space && parent.space.permId.permId === sample.space.permId.permId)  ) {
                                var node = this._createSampleNode(sample);
                                results.nodes.push(node);
                            }
                        });
                        resolve(results)
                    }
                }
            )
        })
    }

    async _loadNodesSpaceProjects(params) {
        var projectRules = { [Util.guid()]: { type: "Attribute", name: "SPACE", value: params.node.space } }
        var projectFetchOptions = { only: true, sortings: [] }

        if (params.node.sortings) {
            var projectSorting = params.node.sortings.find((sorting) => sorting.id === params.node.sortingId)
            if (projectSorting) {
                projectFetchOptions.sortings = projectSorting.server
            }
        }

        return new Promise((resolve) => {
            mainController.serverFacade.searchForProjectsAdvanced(
                { entityKind: "PROJECT", logicalOperator: "AND", rules: projectRules },
                projectFetchOptions,
                (searchResult) => {
                    var results = { nodes: [], totalCount: searchResult.totalCount }

                    searchResult.objects.forEach((project) => {
                        if (!this._isQueriesProject(project)) {
                            results.nodes.push(this._createProjectNode(project))
                        }
                    })

                    this._filterResultsByChildrenInAndNotIn(params, results)

                    resolve(results)
                }
            )
        })
    }

    async _loadNodesSpace(params) {
        var samplesFolderNode = this._createSpaceSamplesNode()
        samplesFolderNode.space = params.node.object.id
        samplesFolderNode.sortingId = params.node.sortingId
        samplesFolderNode.id = params.node.id
        var loadSamplesPromise = this._loadNodesSpaceSamples({
            node: samplesFolderNode,
            offset: params.offset || 0,
            limit: params.limit || this.LOAD_LIMIT,
            sortings: this.SORTINGS_BY_NAME_AND_REGISTRATION_DATE,
            childrenIn: params.childrenIn
        })

        var projectsFolderNode =this._createSpaceProjectsNode();
        projectsFolderNode.space = params.node.object.id
        projectsFolderNode.sortingId = params.node.sortingId
        var loadProjectsPromise = this._loadNodesSpaceProjects({
            node: projectsFolderNode,
            offset: params.offset || 0,
            limit: params.limit || this.LOAD_LIMIT,
            sortings: this.SORTINGS_BY_CODE_AND_REGISTRATION_DATE,
        })

        var [projectsResults, samplesResults] = await Promise.all([loadProjectsPromise, loadSamplesPromise])

        var results = {
            nodes: [],
            totalCount: 0,
        }

        if (samplesResults.totalCount > 0) {
            var promises = []
             if(params.childrenIn) {
                samplesResults.nodes = samplesResults.nodes
                       .filter(x => params.childrenIn.some(y => y.object.id === x.object.id));
            }
            if(params.childrenNotIn) {
                samplesResults.nodes = samplesResults.nodes
                       .filter(x => !params.childrenNotIn.some(y => y.object.id === x.object.id));
            }

            samplesResults.nodes.forEach((sampleNode) => {
                  promises.push(this._loadNodesSample({
                          node: sampleNode,
                          offset: 0,
                          limit: this.LOAD_LIMIT,
                          sortings: this.SORTINGS_BY_NAME_AND_REGISTRATION_DATE,
                      }));

            });
            await Promise.all(promises);

            if (projectsResults.totalCount > 0) {
                results.nodes.push(samplesFolderNode)
                results.totalCount++
                results.nodes.push(projectsFolderNode)
                results.totalCount++
            } else {
                samplesResults.nodes.forEach((sampleNode) => {
                    //space samples only
                    results.nodes.push(sampleNode);
                })
                results.totalCount = samplesResults.totalCount;
            }
        } else if (projectsResults.totalCount > 0) {
            projectsResults.nodes.forEach((projectNode) => {
                // projects only
                results.nodes.push(projectNode);
            })
            results.totalCount = projectsResults.totalCount;
        }

        return results
    }

