function MainHeaderController() {
    this._mainController = mainController
    this._mainHeaderModel = new MainHeaderModel()
    this._mainHeaderView = new MainHeaderView(this)
    var _this = this;

    var MOBILE_MODE = $(window).width < LayoutManager.TABLET_SIZE;

    var MIN_LENGTH = 3

    //
    // Init method that builds the menu object hierarchy
    //
    this.init = function ($container, initCallback) {
        _this._mainHeaderModel.$container = $container;
        _this._mainHeaderModel.currentPage = "lab_notebook";

        _this._mainHeaderView.repaint($container)

        initCallback()
    }

    this.getCurrentPage = function() {
        return this._mainHeaderModel.currentPage;
    }

    this.handlePageChange = function(event, value) {
        if(MOBILE_MODE) {
            _this._mainHeaderView.repaint(_this._mainHeaderModel.$container);

        } else {
            _this._mainHeaderModel.currentPage = value;
            mainController.tabContent.changePage(value);
            var tabInfo = mainController.tabContent.getCurrentTabInfo();
            if(tabInfo) {
                var node = JSON.parse(tabInfo.node);
                mainController.sideMenu.changeCurrentTree(value, node);
            } else {
                mainController.sideMenu.changeCurrentTree(value);
            }
            if(mainController.sideMenu.isCollapsed) {
                mainController.sideMenu.expandSideMenu();
            }
            _this._mainHeaderView.repaint(_this._mainHeaderModel.$container);
        }
    }

    this.setSearchDomains = function(searchDomains) {
        _this._mainHeaderModel.searchDomains = searchDomains;
        _this._mainHeaderModel.searchDomain = searchDomains[0];
    }

    this.handleSearchDomainChange = function(event) {
        var index = event.target.value;
        _this._mainHeaderModel.searchDomain = _this._mainHeaderModel.searchDomains[index];
    }

    this.searchFunction = function(page, searchText) {
        var page = page;
        var searchText = searchText;

        if (searchText.length < MIN_LENGTH) {
            Util.showInfo(
                "The minimum length for a global text search is " + MIN_LENGTH + " characters.",
                function () {},
                true
            )
            return false
        }

        var searchDomain = _this._mainHeaderModel.searchDomain.name;
        var searchDomainLabel = _this._mainHeaderModel.searchDomain.label;


        var argsMap = {
            searchText: searchText,
            searchDomain: searchDomain,
            searchDomainLabel: searchDomainLabel,
            page: page,
        }
        var argsMapStr = JSON.stringify(argsMap)


        mainController.changeView("showSearchPage", argsMapStr)

    }

    this.handleLogout = function() {
        mainController.sideMenu.finalize()
        $("body").addClass("bodyLogin")
        sessionStorage.setItem("forceNormalLogin", mainController.loggedInAnonymously)
        mainController.loggedInAnonymously = false
        mainController.serverFacade.logout()
    }

    this.navigateToTabByEntity = function(type, spaceCode, permId) {
        var tree = this._getTreeFromSpaceCode(spaceCode);
        var node = null
        if(permId) {
            node = {
                id: permId,
            };
            switch(type) {
                case "SPACE":
                    node.type = "SPACE"
                    break;
                case "PROJECT":
                    node.type = "PROJECT"
                    break;
                case "COLLECTION":
                    node.type = "EXPERIMENT"
                    break;
                case "OBJECT":
                    node.type = "SAMPLE"
                    break;
                case "DATASET":
                    node.type = "DATASET"
                    break;
            }
        }
        if(tree !== _this._mainHeaderModel.currentPage) {
            _this._mainHeaderModel.currentPage = tree;
            _this._mainHeaderView.repaint(_this._mainHeaderModel.$container);
            _this._mainController.tabContent.changePage(tree)
            _this._mainController.sideMenu.changeCurrentTree(tree, node)
        }
    }

    this._getTreeFromSpaceCode = function(spaceCode) {
        if(spaceCode) {
            if(SettingsManagerUtils.isLabNotebookSpace(spaceCode)) {
                return "lab_notebook";
            } else if(profile.settingsSpaces.includes(spaceCode)) {
                return "tools";
            } else {
                return "lims";
            }
        } else {
            return "lab_notebook";
        }
    }

    this.navigateToTab = function(type) {
        if(type) {
            type = type.toUpperCase();
        }
        var tabTypes = ["LAB_NOTEBOOK", "LIMS", "TOOLS"]
        var tree = _this._mainHeaderModel.currentPage;
        if(tabTypes.includes(type)) {
            tree = type.toLowerCase();
        }
        if(tree !== _this._mainHeaderModel.currentPage) {
            _this._mainHeaderModel.currentPage = tree;
            _this._mainController.sideMenu.changeCurrentTree(tree)
            _this._mainController.tabContent.changePage(tree)
            _this._mainHeaderView.repaint(_this._mainHeaderModel.$container);
        }
    }


}
;
function MainHeaderModel() {
    this.$container = null;
    this.currentPage = null;
}
;
function MainHeaderView(controller) {
    this._controller = controller;

    this.repaint = function ($container) {
        this._$container = $container

        if(LayoutManager.isMobile()) {
            LayoutManager.hideMainHeader();
            return;
        } else {
            LayoutManager.showMainHeader();
        }

        if(!$container.attr('id')) {
            $container.attr('id', 'mainHeader-' + mainController.getNextId())
        }

        $container.css('background-color', 'rgb(248, 248, 248)');
        $container.css('display', 'flex');
        $container.css('width', 'flex');

        var barcodeFunction = null;
        if(profile.mainMenu.showBarcodes) {
            barcodeFunction = () => { BarcodeUtil.readBarcodeFromScannerOrCamera(); }
        }

        var searchDomains = profile.getSearchDomains();

        this._controller.setSearchDomains(searchDomains);

        // Need to convert the callback-based API to a Promise-based one
        var sendChatBotMessage = function(message, sessionId) {
            return new Promise((resolve, reject) => {
                try {
                    mainController.serverFacade.sendChatBotMessage(message, sessionId, function(response) {
                        if (response && response.result) {
                            resolve(response.result);
                        } else {
                            reject(new Error('Invalid response from server'));
                        }
                    });
                } catch (error) {
                    reject(error);
                }
            });
        }

        let tabs = [];
        if (!profile.isAdmin) {
            if(profile.mainMenu.showLabNotebook) {
                tabs.push({page: "lab_notebook", label: "Lab Notebook"})
            }
            if(profile.mainMenu.showInventory || profile.mainMenu.showStock) {
                tabs.push({page: "lims", label: "Inventory"})
            }
            if(profile.mainMenu.showTools) {
                tabs.push({page: "tools", label: "Tools"})
            }
        } else {
            tabs = [
                {page: "lab_notebook", label: "Lab Notebook"},
                {page: "lims", label: "Inventory"},
                {page: "tools", label: "Tools"},
            ];
        }

        let props = {
            pageChangeFunction: this._controller.handlePageChange,
            searchFunction: this._controller.searchFunction,
            logoutFunction: this._controller.handleLogout,
            searchText: "",
            currentPage: this._controller.getCurrentPage(),
            userName: mainController.serverFacade.getUserId(),
            tabs: tabs,
            barcodeFunction: barcodeFunction,
            showChatbot: profile.mainMenu.showChatAgent,
            sendMessageCallback: sendChatBotMessage,
            searchDomains: searchDomains,
            searchDomainChangeFunction: this._controller.handleSearchDomainChange,
            menuStyles: {
                searchBox: {
                    width: '500px',
                    transition: "width 0.3s",
                },
                searchField: {
                    'fontSize': "14px",
                    height: '29.125px'
                }
            }
        }

        let Menu = React.createElement(window.NgComponents.default.Menu, props)
        return NgComponentsManager.renderComponent(Menu, $container.get(0), true);
    }

}
