function InstanceSettingsView(instanceSettingsController, instanceSettingsModel) {
	this._instanceSettingsController = instanceSettingsController;
	this._instanceSettingsModel = instanceSettingsModel;
	this.settingsContainer = $("<div>");
	this.commentsAddButton = $("<div>");


    this.repaint = function($container) {

        var tableModel = this._getTableModel();
        tableModel.fullWidth = false;

        // define columns
        tableModel.columns = [{ label : "Setting", width: "20%"}, { label : "Value", width: "80%"}];
        tableModel.rowBuilders = {
            "Setting" : function(rowData, rowType) {
                return $("<span>").text(rowData.label).attr('varname', rowData.varname);
            },
            "Value" : function(rowData, rowType) {
                if(rowType === "BOOLEAN") {
                    var $checkbox = $("<input>", { type : "checkbox", name : "cb" });
                        if (rowData.value) {
                            $checkbox.attr("checked", true);
                        }
                        return $checkbox;
                } else if(rowType === "INTEGER") {
                    var $number = FormUtil._getNumberInputField(rowData.label, '', '1', false);
                    $number.attr("value", rowData.value);
                    return $number;
                } else if(rowType === "REGEX") {
                    var $regex = FormUtil._getInputField("text", rowData.label, '', null, false);
                    $regex.attr("value", rowData.value);
                    return $regex;
                } else if(rowType === "STRING") {
                    var $text = FormUtil._getInputField("text", rowData.label, '', null, false);
                    $text.attr("value", rowData.value);
                    return $text;
                } else {
                    return null;
                }
            }
        };

        // add data
        for(setting of this._instanceSettingsModel.getSettings()) {
            tableModel.addRow({
                label: setting.label,
                value: this._getValueForSetting(setting.variableName, setting.type, setting.default),
                varname : setting.variableName
            }, setting.type);
        }


        // transform output
        tableModel.valuesTransformer = function(values) {
            var settings = {};
            for (var value of values) {
                settings[value["Setting"]] = value["Value"];
            }
            return settings;
        };

        $container.append(this._getTable(tableModel));
        this._tableModel = tableModel;
    }

    this.getValues = function() {
        return this._tableModel.getValues();
    }

    this._getValueForSetting = function(variableName, type, defaultValue) {
        var profileToEdit = this._instanceSettingsModel.profileToEdit;
        var mainProfile = mainController.profile;
        if(profileToEdit[variableName]) {
            return profileToEdit[variableName];
        }
        if(mainProfile[variableName]) {
            return mainProfile[variableName];
        }
        return defaultValue;
    }

    this._getTableModel = function() {
        var tableModel = {};
        tableModel.columns = []; // array of elements with label and optional width
        tableModel.rowBuilders = {}; // key (column name); value (function to build widget)
        tableModel.rows = []; // array of maps with key (column name); value (widget)
        tableModel.rowExtraBuilder = null; // optional builder for expandable component per row
        tableModel.rowExtras = []; // array of extras corresponding to the rows
        tableModel.rowExtraModels = [] // row extra models can be placed here. models need getValues() function
        tableModel.dynamicRows = false; // allows adding / removing rows
        tableModel.fullWidth = true; // table is drawn using the full width if true
        tableModel.valuesTransformer = function(values) { return values }; // optional transformer
        tableModel.getValues = (function() {
            var values = [];
            for (var i of Object.keys(tableModel.rows)) {
                var row = tableModel.rows[i];
                var rowValues = {};
                for (var column of tableModel.columns) {
                    var $widget = row[column.label];
                    var value = this._getWidgetValue($widget);
                    rowValues[column.label] = value;
                }
                if (tableModel.rowExtraModels.length === tableModel.rows.length) {
                    rowValues.extraValues = tableModel.rowExtraModels[i].getValues();
                }
                values.push(rowValues);
            }
            return tableModel.valuesTransformer(values);
        }).bind(this);
        tableModel.addRow = function(rowData, rowType) {
            var rowWidgets = {};
            for (var column of tableModel.columns) {
                var rowBuilder = tableModel.rowBuilders[column.label];
                rowWidgets[column.label] = rowBuilder(rowData, rowType);
            }
            tableModel.rows.push(rowWidgets);
            if (tableModel.rowExtraBuilder) {
                tableModel.rowExtras.push(tableModel.rowExtraBuilder(rowData));
            }
            return rowWidgets;
        };
        return tableModel;
    }

    this._getWidgetValue = function($widget) {
        if ($widget.is("span")) {
            if($widget.attr('varname')) {
                return $widget.attr('varname');
            }
            return $widget.text();
        } else if ($widget.is("input") && $widget.attr("type") === "checkbox") {
            return $widget.is(":checked");
        } else {
            return $widget.val();
        }
    }

    this._getTable = function(tableModel, canRemoveFunction) {
        var $table = $("<table>", { class : "table borderless table-compact" });
        if (tableModel.fullWidth != true) {
            $table.css("width", "initial");
        }
        // head
        var $thead = $("<thead>");
        var $trHead = $("<tr>");
        if (tableModel.rowExtraBuilder) {
            $trHead.append($("<th>").css("width", "30px"));
        }
        for (var column of tableModel.columns) {
            var $th = $("<th>").css("vertical-align", "middle").text(column.label);
            if (column.width) {
                $th.css("width", column.width);
            }
            $trHead.append($th);
        }
        // add row button
        if (tableModel.dynamicRows) {
            var $addButton = $("<a>", { class : "btn btn-default" })
                        .append($("<span>", { class : "glyphicon glyphicon-plus" } ));
            if (this._instanceSettingsModel.mode === FormMode.VIEW) {
                $addButton.addClass("disabled");
            } else {
                $addButton.on("click", (function() {
                    var rowWidgets = tableModel.addRow({});
                    if (tableModel.rowExtraBuilder) {
                        var $extra = tableModel.rowExtras[tableModel.rowExtras.length-1];
                        this._addRow($tbody, tableModel, rowWidgets, $extra);
                    } else {
                        this._addRow($tbody, tableModel, rowWidgets);
                    }
                }).bind(this))
            }
            $trHead.append($("<th>").css("width", "80px").append($addButton));
        }
        $thead.append($trHead);
        $table.append($thead);
        // body
        var $tbody = $("<tbody>");
        // keys in reverse order because we are adding rows on top
        for (var i of Object.keys(tableModel.rows).reverse()) {
            var row = tableModel.rows[i];

            if (tableModel.rowExtraBuilder) {
                // add extra as row after actual row
                var $extra = tableModel.rowExtras[i];
                this._addRow($tbody, tableModel, row, $extra, canRemoveFunction);
            } else {
                this._addRow($tbody, tableModel, row, null, canRemoveFunction);
            }
        }
        $table.append($tbody);
        return $table
    }


    this._addRow = function($tbody, tableModel, tableModelRow, $extra, canRemoveFunction) {
        var $tr = $("<tr>");
        $tbody.prepend($tr);
        var $extraRow = null;
        var rowIndex = tableModel.rows.indexOf(tableModelRow);

        // add expand / collapse for extra
        if ($extra) {
            // create extra row
            var colspan = tableModel.columns.length + 1;
            if (tableModel.dynamicRows) {
                colspan++;
            }
            $extraRow = $("<tr>")
                .append($("<td>").css({"padding-left" : "50px", "padding-right" : "50px"}).attr("colspan", colspan)
                    .append($extra));
            // hiding / showing extra row
            $extraRow.hide();
            var $td = $("<td>");
            var $expandCollapse = $("<div>", { class : "glyphicon glyphicon-plus-sign" }).css("vertical-align", "middle");
            $expandCollapse.on("click", (function($extraRow, $expandCollapse) {
                $extraRow.toggle();
                if ($extraRow.is(":visible")) {
                    $expandCollapse.removeClass("glyphicon-plus-sign").addClass("glyphicon-minus-sign");
                } else {
                    $expandCollapse.removeClass("glyphicon-minus-sign").addClass("glyphicon-plus-sign");
                }
            }).bind(this, $extraRow, $expandCollapse));
            $tr.append($td);
            $td.append($expandCollapse);
        }

        for (var column of tableModel.columns) {
            var $td = $("<td>");
            $tr.append($td);
            var $widget = tableModelRow[column.label];
            $td.append($widget);
            // disbale widget if in view mode
            if (this._instanceSettingsModel.mode === FormMode.VIEW || (canRemoveFunction && !canRemoveFunction(tableModel.rows[rowIndex]))) {
                $widget.prop("disabled", true);
            }
        }
        // remove row button if in edit mode
        if (tableModel.dynamicRows) {
            $removeButton = $("<a>", { class : "btn btn-default" })
                        .append($("<span>", { class : "glyphicon glyphicon-minus" }));
            if (this._instanceSettingsModel.mode === FormMode.VIEW) {
                $removeButton.addClass("disabled");
            } else {
                if(!canRemoveFunction || canRemoveFunction(tableModel.rows[rowIndex])) {
                    $removeButton.on("click", function() {
                        $tr.remove();
                        if ($extraRow) {
                            $extraRow.remove();
                        }
                        var rowIndex = tableModel.rows.indexOf(tableModelRow);
                        tableModel.rows.splice(rowIndex, 1);
                        if (tableModel.rowExtraModels) {
                            tableModel.rowExtraModels.splice(rowIndex, 1);
                        }
                    });
                } else {
                    $removeButton.addClass("disabled");
                }
            }
            $tr.append($("<td>").append($removeButton));
        }
        // add extra row
        if ($extraRow) {
            $tbody.append($extraRow);
        }
    }


}
;
function RootNodeSettings(mode, profileToEdit)
{
    this._container = null;
    this._mode = mode;
    this._profileToEdit = profileToEdit;
    this.selected = null;
    this._advancedEntitySearchDropdown = null;

    var _refreshableFields = [];


    this.init = function($container) {
        var container = $("<div>").css("padding-left", "8px");
        $container.append(container);
        this._container = container;
        this.repaint(this._container);
    }

    this.repaint = function(container) {
        var _this = this;

        var radioDiv = $("<p>");
        var $inputDiv = $("<div>");

        function onRadioChange() {
            var value = $(this).val();
            _this.selected = { type: value };
            if(value === "identifier") {
                $inputDiv.empty();
                _this._advancedEntitySearchDropdown = new AdvancedEntitySearchDropdown(false, true, "search entity use as root node",
                    true, false, false, true, true);
                _this._advancedEntitySearchDropdown.onChange(function(selected) {
                    if(selected.length > 0) {
                        _this.selected = {type: value, value: selected[0]};
                    } else {
                        _this.selected = null;
                    }
                });
                _this._advancedEntitySearchDropdown.init($inputDiv);
                if(_this._mode === FormMode.VIEW) {
                    $inputDiv.find("*").prop("disabled", true);
                }
            } else {
                _this._advancedEntitySearchDropdown = null;
                $inputDiv.empty();
            }

        }

        var $radioNone = $("<input>", { type: "radio", name: "rootNode", value: "none"}).on("change", onRadioChange);
        var $radioHomeSpace = $("<input>", { type: "radio", name: "rootNode", value: "homeSpace"}).on("change", onRadioChange);
        var $radioIdentifier = $("<input>", { type: "radio", name: "rootNode", value: "identifier"}).on("change", onRadioChange);

        if(this._mode === FormMode.VIEW) {
            $radioNone.prop("disabled", true);
            $radioHomeSpace.prop("disabled", true);
            $radioIdentifier.prop("disabled", true);
        }

        if(this._profileToEdit.rootNodeSettings) {
            if(this._profileToEdit.rootNodeSettings.type === "none") {
                $radioNone.attr("checked", "");
            } else if(this._profileToEdit.rootNodeSettings.type === "homeSpace") {
                $radioHomeSpace.attr("checked", "");
            } else {
                $radioIdentifier.attr("checked", "");
                $radioIdentifier.trigger("change");
                _this._advancedEntitySearchDropdown.addSelected(this._profileToEdit.rootNodeSettings.value);
            }
            this.selected = this._profileToEdit.rootNodeSettings;
        }

        $radioNone.refresh = function() {
            $(this).off("change");
            $(this).on("change", onRadioChange);
        }
        _refreshableFields.push($radioNone);

        $radioHomeSpace.refresh = function() {
            $(this).off("change");
            $(this).on("change", onRadioChange);
        }
        _refreshableFields.push($radioHomeSpace);

        $radioIdentifier.refresh = function() {
            $(this).off("change");
            $(this).on("change", onRadioChange);
        }
        _refreshableFields.push($radioIdentifier);



        radioDiv.append($("<label>", {style: "font-weight: normal;" }).append($radioNone).append($("<span>", {text: " None"}))).append($("<br>"));
        radioDiv.append($("<label>", {style: "font-weight: normal;" }).append($radioHomeSpace).append($("<span>", {text: " Home Space"}))).append($("<br>"));
        radioDiv.append($("<label>", {style: "font-weight: normal;" }).append($radioIdentifier).append($("<span>", {text: " Identifier"}))).append($("<br>"));

        radioDiv.append($inputDiv);
        container.append(FormUtil.getFieldForComponentWithLabel(radioDiv, ""));
    }

    this.refresh = function() {
        if(this._advancedEntitySearchDropdown) {
            this._advancedEntitySearchDropdown.refresh();
        }
        for(var field of _refreshableFields) {
            field.refresh();
        }

    }

    this.getValue = function() {
        return this.selected;
    }
}
;
function ToolbarSettings(mode, toolbarSettings) {
    this._container = null;
    this._mode = mode;
    this.selected = null;
    this._toolbarSettings = toolbarSettings;
    this._pillButtons = [];
    this._toggleValue = false;
    this._$toggleAllBtn = null;

    var _refreshableFields = [];

    const groupedToolbars = {
        'Buttons':
            [
                {name: "CREATE_PROJECT", icon: "PROJECT"},
                {name: "CREATE_FOLDER", icon: "FOLDER"},
                {name: "CREATE_ENTRY", icon: "ENTRY"},
                {name: "CREATE_OTHER", icon: "ENTRY"},
                {name: "UPLOAD_DATASET", icon: "DATA"},
                {name: "ARCHIVE", icon: "ARCHIVE_NOT_REQUESTED"},
                {name: "EDIT", icon: "EDIT"},
            ],
        'Dropdown': [
            {name: "MOVE", icon: ""},
            {name: "DELETE", icon: ""},
            {name: "COPY", icon: ""},
            {name: "PRINT", icon: ""},
            {name: "BARCODE", icon: ""},
            {name: "HIERARCHY_GRAPH", icon: ""},
            {name: "HIERARCHY_TABLE", icon: ""},
            {name: "UPLOAD_DATASET_HELPER", icon: ""},
            {name: "TEMPLATES", icon: ""},
            {name: "EXPORT_ALL", icon: ""},
            {name: "MANAGE_ACCESS", icon: ""},
            {name: "FREEZE", icon: ""},
            {name: "HISTORY", icon: ""},
        ],

    };

    this.refresh = function() {
        for(let field of _refreshableFields) {
            field.refresh();
        }
    }

    this.init = function($container) {
        var container = $("<div>");
        $container.append(container);
        this._container = container;

        this.repaint(this._container);
    }

    this.isAnySettingEnabled = function() {
        for (let setting of Object.keys(this._toolbarSettings)) {
            if(this._toolbarSettings[setting]) {
                return true;
            }
        }
        return false;
    }

    this.isAnySettingDisabled = function() {
        for (let setting of Object.keys(this._toolbarSettings)) {
            if(!this._toolbarSettings[setting]) {
                return true;
            }
        }
        return false;
    }

    this.repaint = function(container) {
        var _this = this;
        var toggleAll = function() {
            let isAnyDisabled = _this.isAnySettingDisabled();
            if(!_this._toggleValue ||  !isAnyDisabled) {
                _this._toggleValue = !_this._toggleValue;
            }
            _this._$toggleAllBtn.toggleClass('tbe-pill-on', _this._toggleValue).attr('aria-checked', _this._toggleValue ? 'true' : 'false');
            for(let pillButton of _this._pillButtons) {
                pillButton.toggleClass('tbe-pill-on', _this._toggleValue).attr('aria-checked', _this._toggleValue ? 'true' : 'false');
            }
            for(let setting of Object.keys(_this._toolbarSettings)){
                _this._toolbarSettings[setting] = _this._toggleValue;
            }
        }

        this._toggleValue = this.isAnySettingEnabled();

        this._$toggleAllBtn = $('<div>')
            .addClass('tbe-pill')
            .toggleClass('tbe-pill-on', this._toggleValue)
            .attr('role', 'checkbox')
            .attr('aria-checked', this._toggleValue)
            .text('Toggle all')
            .on('click', toggleAll);
        this._$toggleAllBtn.refresh = function() {
            $(this).off('click');
            $(this).on('click', toggleAll);
        }


        var $header = $('<div>').addClass('tbe-box-header').append(
            $('<span>').addClass('tbe-box-title').text('Toolbar') ,
        );

        if(_this._mode !== FormMode.VIEW) {
            $header.append(this._$toggleAllBtn);
            _refreshableFields.push(this._$toggleAllBtn);
        }

        var $toolbar = $("<div>", {"style": "padding-left:35px;"});

        var createPill = function(element) {
            let name = element.name;
            let value = _this._toolbarSettings[name];
            let key = LabelUtil.getToolbarLabelInfo(name);



            var $pill = $('<div>')
                .addClass('tbe-pill')
                .toggleClass('tbe-pill-on', value)
                .attr('data-key', name)
                .attr('role', 'checkbox')
                .attr('aria-checked', value ? 'true' : 'false')
                .attr('title', key.tooltip)

            if(IconUtil.hasToolbarIconType(element.icon)) {
                let iconType = IconUtil.getToolbarIconType(element.icon);
                let icon = IconUtil.getIcon(iconType);
                $pill.append(icon);
            }

            $pill.append($('<span>').addClass('tbe-pill-label').append(key.label))

            if(_this._mode === FormMode.VIEW) {
                $pill.css('cursor', 'auto');
            }


            var toggle = function () {
                if(_this._mode !== FormMode.VIEW) {
                    let value = !_this._toolbarSettings[$(this).attr('data-key')];
                    _this._toolbarSettings[$(this).attr('data-key')] = value;
                    $pill.toggleClass('tbe-pill-on', value).attr('aria-checked', value ? 'true' : 'false');

                    if (_this._toggleValue !== _this.isAnySettingEnabled()) {
                        _this._toggleValue = !_this._toggleValue;
                        _this._$toggleAllBtn.toggleClass('tbe-pill-on', _this._toggleValue).attr('aria-checked', _this._toggleValue ? 'true' : 'false');
                    }
                }
            };
            $pill.on('click', toggle);
            $pill.refresh = function() {
                $(this).off('click');
                $(this).on('click', toggle);
            }
            return $pill;
        }

        var settingKeys = new Set(Object.keys(_this._toolbarSettings));
        var keys = new Set();

        Object.keys(groupedToolbars).forEach(toolbarGroupName => {
            var hasTag = false;
            var group = $("<span>", {"style": "font-size:medium; font-weight: bold;"})
                .append($("<span>", {"style": "margin-left:17px"}).text(toolbarGroupName+": "));
            groupedToolbars[toolbarGroupName].forEach(tag => {
                if(settingKeys.has(tag.name)) {
                    hasTag = true;
                    keys.add(tag.name);
                    let pill = createPill(tag);
                    this._pillButtons.push(pill);
                    group.append(pill);
                    _refreshableFields.push(pill)
                }
            })

            if(toolbarGroupName === 'Dropdown') {
                for(let setting of Object.keys(_this._toolbarSettings).sort()) {
                    if(!keys.has(setting)) {
                        hasTag = true;
                        keys.add(setting);
                        let pill = createPill({name:setting, icon:null});
                        this._pillButtons.push(pill);
                        group.append(pill);
                        _refreshableFields.push(pill)
                    }
                }
            }

            if(hasTag) {
                $toolbar.append(group);
            }
        });

        container.append($header);
        container.append($toolbar);
        container.append($("<br>"));
    }

    this.getValue = function() {
        return this._toolbarSettings;
    }

}
