function MoveEntityController(entityType, entityPermIds, optionalPostAction) {
	var moveEntityModel = new MoveEntityModel();
	var moveEntityView = new MoveEntityView(this, moveEntityModel);
	
	var searchAndCallback = function(callback) {
        if (_.isString(entityPermIds)) {
            entityPermIds = entityPermIds.trim()
            var criteria = { entityKind : entityType, logicalOperator : "AND", rules : { "UUIDv4" : { type : "Attribute", name : "PERM_ID", value : entityPermIds } } };
        } else {
            var criteria = { entityKind : entityType, logicalOperator : "OR", rules : {} };
            for(var pIdx = 0; pIdx < entityPermIds.length; pIdx++) {
                criteria.rules["UUIDv4_" + pIdx] = { type : "Attribute", name : "PERM_ID", value : entityPermIds[pIdx] };
            }
        }

		switch(entityType) {
			case "EXPERIMENT":
				mainController.serverFacade.searchForExperimentsAdvanced(criteria, null, callback);
				break;
			case "SAMPLE":
				mainController.serverFacade.searchForSamplesAdvanced(criteria, { only : true, withType: true, withExperiment: true, withProject: true, withSpace: true }, callback);
				break;
			case "DATASET":
				mainController.serverFacade.searchForDataSetsAdvanced(criteria, null, callback);
				break;
			case "PROJECT":
				mainController.serverFacade.searchForProjectsAdvanced(criteria, null, callback);
				break;
		}
	};
	
	this.init = function() {
		searchAndCallback(function(result) {
			moveEntityModel.entity = result.objects[0];
			moveEntityModel.entities = result.objects;
			moveEntityView.repaint();
		});
	};
	
	var waitForIndexUpdate = function() {
		searchAndCallback(function(result) {
			var entity = result.objects[0];
			var found = false;
			switch(entityType) {
				case "EXPERIMENT":
					found = entity.getProject().getIdentifier().identifier === moveEntityModel.selected.getIdentifier().identifier;
					break;
				case "SAMPLE":
				    var selectedEntityType = moveEntityModel.selected["@type"]
				    switch(selectedEntityType) {
                        case "as.dto.project.Project":
                            found = entity.getExperiment() == null && entity.getProject().getIdentifier().identifier === moveEntityModel.selected.getIdentifier().identifier;
                            break;
                        case "as.dto.experiment.Experiment":
                            found = entity.getExperiment().getIdentifier().identifier === moveEntityModel.selected.getIdentifier().identifier;
                            break;
                        case "as.dto.space.Space":
                            found = entity.getExperiment() == null && entity.getProject() == null && entity.getSpace().getPermId().permId === moveEntityModel.selected.getPermId().permId;
                            break;
                    }

					break;
				case "DATASET":
					found = (entity.getSample() && entity.getSample().getIdentifier().identifier === moveEntityModel.selected.getIdentifier().identifier)
							||
							(entity.getExperiment() && entity.getExperiment().getIdentifier().identifier === moveEntityModel.selected.getIdentifier().identifier);
					break;
				case "PROJECT":
					found = entity.getSpace().getPermId().identifier === moveEntityModel.selected.getPermId().identifier;
					break;
			}
			
			if(!found) {
				setTimeout(function(){ waitForIndexUpdate(); }, 300);
			} else {
                Util.showSuccess("Moved successfully", async function() {
                    Util.unblockUI();

                    await mainController.sideMenu.refreshNodeParentByPermId(entityType, entity.getPermId().permId); // Refresh old node parent

                    var selectedType = moveEntityModel.selected["@type"]
                    var selectedEntityType = null

                    if(selectedType === "as.dto.space.Space"){
                        selectedEntityType = "SPACE"
                    }else if(selectedType === "as.dto.project.Project"){
                        selectedEntityType = "PROJECT"
                    }else if(selectedType === "as.dto.experiment.Experiment"){
                        selectedEntityType = "EXPERIMENT"
                    }else if(selectedType === "as.dto.sample.Sample"){
                        selectedEntityType = "SAMPLE"
                    }else if(selectedType === "as.dto.dataset.DataSet"){
                        selectedEntityType = "DATASET"
                    }

                    await mainController.sideMenu.refreshNodeByPermId(selectedEntityType, moveEntityModel.selected.getPermId().permId); // New node parent

                    switch(entityType) {
                        case "EXPERIMENT":
                            mainController.changeView("showExperimentPageFromIdentifier",
                                    encodeURIComponent('["' + entity.getIdentifier().identifier + '",false]'));
                            mainController.sideMenu.moveToNodeId(JSON.stringify({type: "EXPERIMENT", id: entity.getPermId().permId}));
                            break;
                        case "SAMPLE":
                            mainController.changeView("showViewSamplePageFromPermId", entity.getPermId().permId);
                            mainController.sideMenu.moveToNodeId(JSON.stringify({type: "SAMPLE", id: entity.getPermId().permId}));
                            break;
                        case "DATASET":
                            mainController.changeView("showViewDataSetPageFromPermId", entity.getPermId().permId);
                            mainController.sideMenu.moveToNodeId(JSON.stringify({type: "DATASET", id: entity.getPermId().permId}));
                            break;
                        case "PROJECT":
                            mainController.changeView("showProjectPageFromIdentifier", entity.getPermId().permId);
                            mainController.sideMenu.moveToNodeId(JSON.stringify({type: "PROJECT", id: entity.getPermId().permId}));
                            break;
                    }
				});
			}
		});
	}
	
	this.move = function(descendants) {
	    var _this = this;
		Util.blockUI();
		
		var done = function() {
			waitForIndexUpdate();
			if(optionalPostAction) {
			    optionalPostAction();
			}
		};

        //only for multiple sample movement
		var doneMultiple = function() {
		    var selectedEntity = moveEntityModel.selected;
		    var selectedEntityType = moveEntityModel.selected["@type"];

		    var callback = async function(resultObject) {
		        var samples = resultObject.objects;
		        samples = samples.map(x => x.permId.permId);
		        var entitiesDone = [];
                switch(selectedEntityType) {
                    case "as.dto.project.Project":
                        var selectedType = "PROJECT";
                        var selectedEntityPermId = selectedEntity.getPermId().getPermId();
                        break;
                    case "as.dto.experiment.Experiment":
                        var selectedType = "EXPERIMENT";
                        var selectedEntityPermId = selectedEntity.getPermId().getPermId();
                        break;
                    case "as.dto.space.Space":
                        var selectedType = "SPACE";
                        var selectedEntityPermId = selectedEntity.getPermId().getPermId();
                        break;
                }
		        for(var i = 0; i < moveEntityModel.entities.length; i++) {
		            var entity = moveEntityModel.entities[i];
		            var permId = entity.permId.permId;
		            if(entitiesDone.includes(permId)) {
		                continue;
		            }
		            //refresh old entities
		            if(entity.getExperiment()) {
		                await mainController.sideMenu.refreshNodeByPermId("EXPERIMENT", entity.getExperiment().getPermId().permId);
		            } else if(entity.getProject()) {
		                await mainController.sideMenu.refreshNodeByPermId("PROJECT", entity.getProject().getPermId().permId);
		            } else {
		                await mainController.sideMenu.refreshNodeByPermId("SPACE", entity.getSpace().getPermId().permId);
		            }
		            if(samples.includes(permId)) {
		                entitiesDone.push(permId);
		            }
		        }
		        await mainController.sideMenu.refreshNodeByPermId(selectedType, selectedEntityPermId);
		        if(descendants) {
		            Util.showSuccess("Moving of " + entitiesDone.length + " objects and their descends has been finished", async function() { Util.unblockUI(); });
		        } else {
		            Util.showSuccess("Moving of " + entitiesDone.length + " objects has been finished", async function() { Util.unblockUI(); });
		        }
		        if(optionalPostAction) {
		            optionalPostAction();
		        }
		    };

		    switch(selectedEntityType) {
                case "as.dto.project.Project":
                    var criteria = {
                                        entityKind : entityType, logicalOperator : "AND",
                                        rules : {
                                            "UUIDv4_0" : { type : "Attribute", name : "PROJECT_PERM_ID", value : selectedEntity.getPermId().permId },
                                            "UUIDv4_1" : { type: "Experiment", name: "NULL.NULL", value: "NULL" }
                                        }
                                   };
                    mainController.serverFacade.searchForSamplesAdvanced(criteria, { only : true }, callback);
                    break;
                case "as.dto.experiment.Experiment":
                    var criteria = { entityKind : entityType, logicalOperator : "AND",
                                        rules : {
                                            "UUIDv4" : { type: "Experiment", name: "ATTR.PERM_ID", value : selectedEntity.getPermId().permId }
                                        }
                                    };
                    mainController.serverFacade.searchForSamplesAdvanced(criteria, { only : true }, callback);
                    break;
                case "as.dto.space.Space":
                    var criteria = {
                                        entityKind : entityType, logicalOperator : "AND",
                                        rules : {
                                            "UUIDv4_0" : { type: "Attribute", name: "SPACE", value : selectedEntity.getPermId().permId },
                                            "UUIDv4_1" : { type: "Project", name: "NULL.NULL", value: "NULL" },
                                            "UUIDv4_2" : { type: "Experiment", name: "NULL.NULL", value: "NULL" }
                                        }
                                    };
                    mainController.serverFacade.searchForSamplesAdvanced(criteria, { only : true }, callback);
                    break;
            }
		};

		var fail = function(error) {
			var msg = JSON.stringify(error);
			if (error && error.data && error.data.message) {
				msg = error.data.message;
			}
			Util.showError("Move failed: " + msg);
		};


        if(moveEntityModel.isNewExperiment && !moveEntityModel.experimentIdentifier) {
            Util.showUserError("Please choose the project and " + ELNDictionary.getExperimentDualName() + " name.", function() {});
            return;
        }

        if(moveEntityModel.isNewExperiment && !moveEntityModel.experimentType) {
            Util.showUserError("Please choose the " + ELNDictionary.getExperimentDualName() + " type.", function() {});
            return;
        }


		var moveEntityFunction = function() {
            switch(entityType) {
                case "EXPERIMENT":
                    require([ "as/dto/experiment/update/ExperimentUpdate"],
                        function(ExperimentUpdate) {
                            var experimentUpdate = new ExperimentUpdate();
                            experimentUpdate.setExperimentId(moveEntityModel.entity.getIdentifier());
                            experimentUpdate.setProjectId(moveEntityModel.selected.getIdentifier());
                            experimentUpdate.setProperties(moveEntityModel.entity.getProperties())
                            mainController.openbisV3.updateExperiments([ experimentUpdate ]).done(done).fail(fail);
                        });
                    break;
                case "SAMPLE":
                    require([ "as/dto/sample/fetchoptions/SampleFetchOptions",
                              "as/dto/sample/update/SampleUpdate", "as/dto/space/id/SpacePermId"],
                        function(SampleFetchOptions, SampleUpdate, SpacePermId) {
                            var doneFunction = moveEntityModel.entities.length === 1 ? done : doneMultiple;

                            var prepareSampleUpdate = function(samplePermId) {
                                var sampleUpdate = new SampleUpdate();
                                sampleUpdate.setSampleId(samplePermId);
                                switch(selectedEntityType) {
                                    case "as.dto.project.Project":
                                        sampleUpdate.setExperimentId(null);
                                        sampleUpdate.setProjectId(moveEntityModel.selected.getPermId())
                                        sampleUpdate.setSpaceId(moveEntityModel.selected.getSpace().getPermId());
                                        break;
                                    case "as.dto.experiment.Experiment":
                                        sampleUpdate.setSpaceId(moveEntityModel.selected.getProject().getSpace().getPermId());
                                        sampleUpdate.setProjectId(moveEntityModel.selected.getProject().getPermId());
                                        sampleUpdate.setExperimentId(moveEntityModel.selected.getPermId())
                                        break;
                                    case "as.dto.space.Space":
                                        sampleUpdate.setExperimentId(null);
                                        sampleUpdate.setProjectId(null);
                                        sampleUpdate.setSpaceId(moveEntityModel.selected.getPermId());
                                        break;
                                }
                                return sampleUpdate;
                            }

                            var permIds = moveEntityModel.entities.map(x => x.getPermId());
                            var selectedEntityType = moveEntityModel.selected["@type"];


                                if (descendants) {
                                    var fetchOptions = new SampleFetchOptions();
                                    fetchOptions.withExperiment();
                                    fetchOptions.withProject();
                                    fetchOptions.withSpace();
                                    fetchOptions.withChildrenUsing(fetchOptions);
                                     mainController.openbisV3.getSamples(permIds, fetchOptions).done(function(map) {
                                        var sampleIdsSet = new Set();
                                        var updates = [];

                                         for(var i = 0; i < moveEntityModel.entities.length; i++) {
                                             var samplesToUpdate = [];
                                             var entity = moveEntityModel.entities[i];
                                             var permId = entity.getPermId();
                                             _this.gatherAllDescendants(samplesToUpdate, sampleIdsSet, map[permId]);

                                             if (entity.getExperiment()) {
                                                 var level = "EXPERIMENT";
                                                 var currentEntity = entity.getExperiment().getPermId().getPermId();
                                             } else if (entity.getProject()) {
                                                 var level = "PROJECT";
                                                 var currentEntity = entity.getProject().getPermId().getPermId();
                                             } else {
                                                 var level = "SPACE";
                                                 var currentEntity = entity.getSpace().getPermId().getPermId();
                                             }

                                             switch (level) {
                                                 case "EXPERIMENT":
                                                     samplesToUpdate.forEach(function (sample) {
                                                         if (sample.getExperiment() != null && currentEntity === sample.getExperiment().getPermId().getPermId()) {
                                                             var sampleUpdate = prepareSampleUpdate(sample.getPermId());
                                                             updates.push(sampleUpdate);
                                                         }
                                                     });
                                                     break;
                                                 case "PROJECT":
                                                     samplesToUpdate.forEach(function (sample) {
                                                         if (sample.getExperiment() == null && sample.getProject() != null && currentEntity === sample.getProject().getPermId().getPermId()) {
                                                             var sampleUpdate = prepareSampleUpdate(sample.getPermId());
                                                             updates.push(sampleUpdate);
                                                         }
                                                     });
                                                     break;
                                                 case "SPACE":
                                                     samplesToUpdate.forEach(function (sample) {
                                                         if (sample.getExperiment() == null && sample.getProject() == null && sample.getSpace() != null && currentEntity === sample.getSpace().getPermId().getPermId()) {
                                                             var sampleUpdate = prepareSampleUpdate(sample.getPermId());
                                                             updates.push(sampleUpdate);
                                                         }
                                                     });
                                                     break;
                                             }
                                         }

                                        mainController.openbisV3.updateSamples(updates).done(doneFunction).fail(fail);
                                    });
                                } else {
                                    var sampleUpdate = permIds.map(x => prepareSampleUpdate(x));
                                    mainController.openbisV3.updateSamples( sampleUpdate ).done(doneFunction).fail(fail);
                                }

                    });


                    break;
                case "DATASET":
                    require([ "as/dto/dataset/update/DataSetUpdate"],
                        function(DataSetUpdate) {
                            var datasetUpdate = new DataSetUpdate();
                            datasetUpdate.setDataSetId(moveEntityModel.entity.getPermId());
                            datasetUpdate.setProperties(moveEntityModel.entity.getProperties())

                            switch(moveEntityModel.selected["@type"]) {
                                case "as.dto.experiment.Experiment":
                                    datasetUpdate.setExperimentId(moveEntityModel.selected.getIdentifier());
                                break;
                                case "as.dto.sample.Sample":
                                    if(moveEntityModel.selected.getExperiment()) {
                                        datasetUpdate.setExperimentId(moveEntityModel.selected.getExperiment().getIdentifier());
                                    }
                                    datasetUpdate.setSampleId(moveEntityModel.selected.getIdentifier());
                                break;
                            }

                            mainController.openbisV3.updateDataSets([ datasetUpdate ]).done(done).fail(fail);
                        });
                    break;
                case "PROJECT":
                    require(["as/dto/project/update/ProjectUpdate"], function (ProjectUpdate) {
                        var projectUpdate = new ProjectUpdate();
                        projectUpdate.setProjectId(moveEntityModel.entity.getIdentifier());
                        projectUpdate.setSpaceId(moveEntityModel.selected.getPermId());
                        mainController.openbisV3.updateProjects([projectUpdate]).done(done).fail(fail);
                    });
                    break;
            }
		}
		if(moveEntityModel.isNewExperiment) {
            var experimentType = moveEntityModel.experimentType;
            var experimentIdentifier = moveEntityModel.experimentIdentifier;
            var projectIdentifier = IdentifierUtil.getProjectIdentifierFromExperimentIdentifier(experimentIdentifier);
            var code = IdentifierUtil.getCodeFromIdentifier(experimentIdentifier)
            mainController.serverFacade.createExperiment(experimentType, projectIdentifier, code, function(result) {
                var experimentPermId = result[0].permId;
                var criteria = { entityKind : "EXPERIMENT", logicalOperator : "AND", rules : { "UUIDv4" : { type : "Attribute", name : "PERM_ID", value : experimentPermId } } };
                mainController.serverFacade.searchForExperimentsAdvanced(criteria, { only: true,
                                                                                       withProject: true,
                                                                                       withProjectSpace: true }, function(experimentSearchResult) {
                    var newExperiment = experimentSearchResult.objects[0];
                    mainController.sideMenu.refreshNodeByPermId("PROJECT", newExperiment.getProject().getPermId().getPermId());
                    moveEntityModel.selected = newExperiment;
                    moveEntityFunction();
                });
            });
        } else {
            moveEntityFunction();
        }
		
	}
	
    this.gatherAllDescendants = function(entities, entityPermIdSet, entity) {
        let permId = entity.permId.permId;
        if(!entityPermIdSet.has(permId)) {
            entityPermIdSet.add(permId);
            entities.push(entity);
            entity.getChildren().forEach(child => this.gatherAllDescendants(entities, entityPermIdSet, child));
        }
    }
}
;
function MoveEntityModel() {
	this.entity;
	this.entities;
	this.selected;
}
;
function MoveEntityView(moveEntityController, moveEntityModel) {

    var $entityBox = $("<div>");
    var $optionalBox = $("<div>");

	this.repaint = function() {
		var $window = $('<form>', { 'action' : 'javascript:void(0);' });

		$window.submit(function() {
			Util.unblockUI();
            var descendants = false;
            var inputs = $window.find("input");
            if (inputs.length > 0) {
                descendants = inputs[0].checked;
            }
			moveEntityController.move(descendants);
		});

		var onlyOne = moveEntityModel.entities.length == 1;
        if(onlyOne) {
            var identifier, type, owningEntityType, owningEntityIdentifier;
            switch(moveEntityModel.entity["@type"]) {
                case "as.dto.experiment.Experiment":
                    identifier = moveEntityModel.entity.getIdentifier();
                    type = moveEntityModel.entity.getType().getCode();
                    owningEntityType = ELNDictionary.Project;
                    owningEntityIdentifier = moveEntityModel.entity.getProject().getIdentifier().identifier;
                    break;
                case "as.dto.sample.Sample":
                    identifier = moveEntityModel.entity.getIdentifier();
                    type = moveEntityModel.entity.getType().getCode();
                    if(moveEntityModel.entity.getExperiment()) {
                        owningEntityType = ELNDictionary.getExperimentDualName();
                        owningEntityIdentifier = moveEntityModel.entity.getExperiment().getIdentifier().identifier;
                    } else if(moveEntityModel.entity.getProject()) {
                        owningEntityType = ELNDictionary.Project;
                        owningEntityIdentifier = moveEntityModel.entity.getProject().getIdentifier().identifier;
                    } else {
                        owningEntityType = ELNDictionary.Space;
                        owningEntityIdentifier = moveEntityModel.entity.getSpace().getCode();
                    }
                    break;
                case "as.dto.project.Project":
                    identifier = moveEntityModel.entity.getIdentifier();
                    type = ELNDictionary.Project;
                    owningEntityType = ELNDictionary.Space;
                    owningEntityIdentifier = moveEntityModel.entity.getSpace().getCode();
                    break;
                case "as.dto.dataset.DataSet":
                    identifier = moveEntityModel.entity.getPermId();
                    type = moveEntityModel.entity.getType().getCode();
                    if(moveEntityModel.entity.getSample()) {
                        owningEntityType = ELNDictionary.sample;
                        owningEntityIdentifier = moveEntityModel.entity.getSample().getIdentifier().identifier;
                    } else {
                        owningEntityType = ELNDictionary.getExperimentDualName();
                        owningEntityIdentifier = moveEntityModel.entity.getExperiment().getIdentifier().identifier;
                    }
                    break;
            }
            $window.append($('<legend>').append("Moving " + identifier));

            $window.append(FormUtil.getFieldForLabelWithText("Type", type));
            $window.append(FormUtil.getFieldForLabelWithText("Current " + owningEntityType.toLowerCase(), owningEntityIdentifier));

		} else {
		    var count = moveEntityModel.entities.length;
		    var header = "Moving (" + count + ") ";
		    switch(moveEntityModel.entity["@type"]) {
                case "as.dto.experiment.Experiment":
                     $window.append($('<legend>').append(header + ELNDictionary.ExperimentsCollection.toLowerCase() + " to:"));
                    break;
                case "as.dto.sample.Sample":
                    $window.append($('<legend>').append(header + ELNDictionary.samples + " to:"));
                    break;
                case "as.dto.project.Project":
                    $window.append($('<legend>').append(header + ELNDictionary.Projects.toLowerCase() + " to:"));
                    break;
                case "as.dto.dataset.DataSet":
                    $window.append($('<legend>').append(header + ELNDictionary.Datasets.toLowerCase() + " to:"));
                    break;
            }

		}

        $window.append($optionalBox);
        if(moveEntityModel.entity["@type"] === "as.dto.sample.Sample") {
            var _this = this;
            $window.append(FormUtil.getFieldForComponentWithLabel(FormUtil.getOptionsRadioButtons("oldOrNewExp",true, ["Existing Space, Project or Experiment/Collection", "New " + ELNDictionary.getExperimentDualName() + ""], function(event) {
                var value = $(event.target).val();
                if(value === "Existing entity") {
                    moveEntityModel.isNewExperiment = false;
                    _this.repaintExistingEntity();
                } else {
                    moveEntityModel.isNewExperiment = true;
                    _this.repaintNewEntity();
                }
            }), "Choose existing Space, Project or Experiment/Collection or create a new " + ELNDictionary.getExperimentDualName() +"?"));
        } else {
            $window.append($('<br>'));
        }

		$window.append($entityBox);
		this.repaintExistingEntity();

        var $btnAccept = $('<input>', { 'type': 'submit', 'class' : 'btn btn-primary', 'value' : 'Accept' });
        var $btnCancel = $('<a>', { 'class' : 'btn btn-default' }).append('Cancel');
        $btnCancel.click(function() {
            Util.unblockUI();
        });

        $window.append('<br>').append($btnAccept).append('&nbsp;').append($btnCancel);

		
		var css = {
				'text-align' : 'left',
				'top' : '15%',
				'width' : '70%',
				'left' : '15%',
				'right' : '20%',
				'overflow' : 'hidden'
		};
		
		Util.blockUI($window, css);
	}

	this.repaintNewEntity = function() {
        var _this = this;
        $entityBox.empty();
        FormUtil.getProjectAndExperimentsDropdown(true, false, true, function($dropdown) {
            $dropdown.attr("id", "future-projects-drop-down");
            //Fields
            var $expTypeField = FormUtil.getExperimentTypeDropdown("future-experiment-type-drop-down", true);
            var $expNameField = FormUtil._getInputField('text', null, 'Future ' + ELNDictionary.getExperimentDualName() + ' Name', null, true);

            //Events
            var newExpEvent = function(event){
                $expNameField.val($expNameField.val().toUpperCase());
                var projectIdentifier = $dropdown.val();
                var projectSpace = IdentifierUtil.getSpaceCodeFromIdentifier(projectIdentifier);
                var projectCode = IdentifierUtil.getCodeFromIdentifier(projectIdentifier);
                var experimentCode = $expNameField.val();
                moveEntityModel.experimentIdentifier = IdentifierUtil.getExperimentIdentifier(projectSpace, projectCode, experimentCode);
            };
            var newTypeEVent = function(event) {
                var value = $(event.target).val();
                moveEntityModel.experimentType = value;
            };

            //Attach Events
            $dropdown.change(newExpEvent);
            $expNameField.keyup(newExpEvent);
            $expTypeField.change(newTypeEVent);

            //Attach Fields
            $entityBox.append(FormUtil.getFieldForComponentWithLabel($dropdown, "Future Project"))
                    .append(FormUtil.getFieldForComponentWithLabel($expTypeField, "Future " + ELNDictionary.getExperimentDualName() + " Type"))
                    .append(FormUtil.getFieldForComponentWithLabel($expNameField, "Future " + ELNDictionary.getExperimentDualName() + " Code"));
        });
    }

    this.repaintExistingEntity = function() {
        var _this = this;
        $entityBox.empty();
        $optionalBox.empty();
        var advancedEntitySearchDropdown = null;

        switch(moveEntityModel.entity["@type"]) {
            case "as.dto.experiment.Experiment":
                advancedEntitySearchDropdown = new AdvancedEntitySearchDropdown(false, true, "search entity to move to",
                        false, false, false, true, false);
                break;
            case "as.dto.sample.Sample":
                $optionalBox.append(FormUtil.getFieldForComponentWithLabel(FormUtil._getBooleanField("move_descendants"),
                        "Click the checkbox if also all descendant " + ELNDictionary.sample
                        + "s (i.e. children, grand children etc.) including their data sets should be moved. "
                        + "Only those descendants are moved which belong to the same entity"
                        + " as this " + ELNDictionary.sample, null, true))
                advancedEntitySearchDropdown = new AdvancedEntitySearchDropdown(false, true, "search entity to move to",
                        true, false, false, true, true);
                break;
            case "as.dto.project.Project":
                advancedEntitySearchDropdown = new AdvancedEntitySearchDropdown(false, true, "search entity to move to",
                        false, false, false, false, true);
                break;
            case "as.dto.dataset.DataSet":
                advancedEntitySearchDropdown = new AdvancedEntitySearchDropdown(false, true, "search entity to move to",
                        true, true, false, false, false);
                break;
        }

        advancedEntitySearchDropdown.onChange(function(selected) {
            moveEntityModel.selected = selected[0];
        });

        advancedEntitySearchDropdown.init($entityBox);
    }
}
;
var ExperimentDataGridUtil = new function() {
	this.getExperimentDataGrid = function(entities, rowClick, multiselectable, heightPercentage) {
		//Fill Columns model
		var columns = [];

		columns.push({
			label : 'Code',
			property : 'code',
			exportableProperty: DataGridExportOptions.EXPORTABLE_FIELD.CODE,
			sortable : true,
			render : function(data, grid) {
				return FormUtil.getFormLink(data.code, "Experiment", data.identifier);
			},
			filter : function(data, filter) {
				return data.code.toLowerCase().indexOf(filter.toLowerCase()) !== -1;
			},
			sort : function(data1, data2, asc) {
				var value1 = data1.code;
				var value2 = data2.code;
				var sortDirection = (asc)? 1 : -1;
				return sortDirection * naturalSort(value1, value2);
			}
		});
        columns.push({
            label : 'Name',
            property : profile.getInternalNamespacePrefix() + 'NAME',
            exportableProperty: DataGridExportOptions.EXPORTABLE_FIELD.PROPERTY(profile.getInternalNamespacePrefix() + "NAME"),
            sortable : true,
            render : function(data) {
                var nameToUse = "";
                if(data[profile.propertyReplacingCode]) {
                    nameToUse = data[profile.propertyReplacingCode];
                }
                return FormUtil.getFormLink(nameToUse, "Experiment", data.identifier);
            }
        });

		columns.push({
			label : 'Identifier',
			property : 'identifier',
			exportableProperty: DataGridExportOptions.EXPORTABLE_FIELD.IDENTIFIER,
			sortable : true,
			render : function(data) {
				return FormUtil.getFormLink(data.identifier, "Experiment", data.identifier);
			},
			filter : function(data, filter) {
				return data.identifier.toLowerCase().indexOf(filter.toLowerCase()) !== -1;
			},
			sort : function(data1, data2, asc) {
				var value1 = data1.identifier;
				var value2 = data2.identifier;
				var sortDirection = (asc)? 1 : -1;
				return sortDirection * naturalSort(value1, value2);
			}
		});
		columns.push({
			label : 'PermId',
			property : 'permId',
			exportableProperty: DataGridExportOptions.EXPORTABLE_FIELD.PERM_ID,
			sortable : true,
			render : function(data) {
				return FormUtil.getFormLink(data.permId, "Experiment", data.identifier);
			},
			filter : function(data, filter) {
				return data.identifier.toLowerCase().indexOf(filter.toLowerCase()) !== -1;
			},
			sort : function(data1, data2, asc) {
				var value1 = data1.identifier;
				var value2 = data2.identifier;
				var sortDirection = (asc)? 1 : -1;
				return sortDirection * naturalSort(value1, value2);
			}
		});
        columns.push({
            label : 'Type',
            property : 'type',
            sortable : true
        });
        
		columns.push({
			label : 'Registrator',
			property : 'registrator',
			exportableProperty: DataGridExportOptions.EXPORTABLE_FIELD.REGISTRATOR,
			sortable : true
		});
		
		columns.push({
			label : 'Registration Date',
			property : 'registrationDate',
			exportableProperty: DataGridExportOptions.EXPORTABLE_FIELD.REGISTRATION_DATE,
			sortable : true,
			renderFilter: function(params) {
				return FormUtil.renderDateRangeGridFilter(params, "TIMESTAMP");
			},
			filter: function(data, filter){
				return FormUtil.filterDateRangeGridColumn(data.registrationDate, filter)
			}
		})

		columns.push({
			label : 'Modifier',
			property : 'modifier',
			exportableProperty: DataGridExportOptions.EXPORTABLE_FIELD.MODIFIER,
			sortable : true
		});

		columns.push({
			label : 'Modification Date',
			property : 'modificationDate',
			exportableProperty: DataGridExportOptions.EXPORTABLE_FIELD.MODIFICATION_DATE,
			sortable : true,
			renderFilter: function(params) {
				return FormUtil.renderDateRangeGridFilter(params, "TIMESTAMP");
			},
			filter: function(data, filter){
				return FormUtil.filterDateRangeGridColumn(data.modificationDate, filter)
			}
		})
		
		//Fill data model
		var getDataList = function(callback) {
			var dataList = [];
			for(var sIdx = 0; sIdx < entities.length; sIdx++) {
				var entity = entities[sIdx];
				var model = {		
                    'id' : entity.permId.permId,
                    'exportableId' : {
                        exportable_kind: DataGridExportOptions.EXPORTABLE_KIND.EXPERIMENT,
                        perm_id: entity.permId.permId,
                        type_perm_id: entity.type.code
                    },
                    '$object' : entity,
                    'code' : entity.code,
                    'identifier' : entity.identifier.identifier,
                    'permId' : entity.permId.permId,
                    'type' : entity.type.code,
                    'registrator' : (entity.registrator)?entity.registrator.userId:null,
                    'registrationDate' : entity.registrationDate ? moment(entity.registrationDate).format("YYYY-MM-DD HH:mm:ss ZZ") : null,
                    'modifier' : (entity.modifier)?entity.modifier.userId:null,
                    'modificationDate' : entity.modificationDate ? moment(entity.modificationDate).format("YYYY-MM-DD HH:mm:ss ZZ") : null
                };
				if(entity.properties) {
                    for(var propertyCode in entity.properties) {
                        model[propertyCode] = entity.properties[propertyCode];
                    }
                }
				dataList.push(model);
			}
			callback(dataList);
		};

        var dynamicColumnsFunc = function(experiments) {
            var foundPropertyCodes = {};
            var foundExperimentTypes = {};
            for(var idx = 0; idx < experiments.length; idx++) {
                var experiment = experiments[idx];
                if(!foundExperimentTypes[experiment.type]) {
                    foundExperimentTypes[experiment.type] = true;
                    var propertyCodes = profile.getAllPropertiCodesForExperimentTypeCode(experiment.type);
                    for(var pIdx = 0; pIdx < propertyCodes.length; pIdx++) {
                        foundPropertyCodes[propertyCodes[pIdx]] = true;
                    }
                }
            }
            var propertyColumnsToSort = SampleDataGridUtil.createPropertyColumns(foundPropertyCodes, experiments);
            FormUtil.sortPropertyColumns(propertyColumnsToSort, entities.map(function(entity){
                return {
                    entityKind: "EXPERIMENT",
                    entityType: entity.type
                }
            }))

            return propertyColumnsToSort;
        }
			
		//Create and return a data grid controller
        var configKey = "EXPERIMENT_TABLE";
        var dataGridController = new DataGridController(null, columns, [], dynamicColumnsFunc, getDataList, rowClick, false, configKey, multiselectable, {
            fileFormat: DataGridExportOptions.FILE_FORMAT.XLS,
            filePrefix: 'collections',
            fileContent: DataGridExportOptions.FILE_CONTENT.ENTITIES
        }, heightPercentage);
		dataGridController.setId("experiment-grid-" + mainController.getNextId())
		return dataGridController;
	}

}
